647	/**
648	 * Reverse a money side-effect that a job committed up-front but never delivered.
649	 * Server actions charge/credit the wallet before enqueuing the worker job (so the
650	 * UI reflects the change immediately); if the job then fails terminally the money
651	 * must be unwound or the customer is charged for a resize that never happened
652	 * (up) or keeps a downgrade credit for hardware they still have (down).
653	 * Idempotent per job: guarded by the RECONCILED audit marker so a re-run can't
654	 * double-reverse.
655	 */
656	async function reconcileFailedJob(job: Job) {
657	  if (job.type !== "RESIZE") return;
658	  const p = (job.payload ?? {}) as { prorateCents?: number; direction?: "up" | "down" };
659	  const cents = p.prorateCents ?? 0;
660	  if (cents <= 0 || !job.serverId) return;
661	
662	  // Idempotency: skip if we already reversed this exact job.
663	  const already = await db.auditLog.findFirst({
664	    where: { action: "server.resize.reconcile", detail: { contains: `job=${job.id}` } },
665	  });
666	  if (already) return;
667	
668	  const server = await db.server.findUnique({ where: { id: job.serverId }, select: { userId: true, hostname: true } });
669	  if (!server) return;
670	
671	  try {
672	    if (p.direction === "up") {
673	      // Upgrade charge never delivered → refund the prorated charge.
674	      await db.$transaction([
675	        db.user.update({ where: { id: server.userId }, data: { balanceCents: { increment: cents } } }),
676	        db.walletTransaction.create({
677	          data: { userId: server.userId, amountCents: cents, description: `Refund: failed upgrade — ${server.hostname}` },
678	        }),
679	      ]);
680	    } else if (p.direction === "down") {
681	      // Downgrade credit was given but hardware unchanged → claw the credit back.
682	      // Guarded so it can never drive the balance negative; if the customer already
683	      // spent it, we log and leave it (best-effort — they keep a small windfall).
684	      await db.$transaction(async (tx) => {
685	        await debitWallet(tx, server.userId, cents);
686	        await tx.walletTransaction.create({
687	          data: { userId: server.userId, amountCents: -cents, description: `Reversed downgrade credit (resize failed) — ${server.hostname}` },
688	        });
689	      });
690	    }
691	    await db.auditLog.create({
692	      data: { userId: server.userId, action: "server.resize.reconcile", detail: `job=${job.id} dir=${p.direction} cents=${cents}` },
693	    });
694	  } catch (e: any) {
695	    // InsufficientBalanceError on a down-reversal is expected/acceptable; record it.
696	    await db.auditLog.create({
697	      data: { userId: server.userId, action: "server.resize.reconcile.uncharged", detail: `job=${job.id} dir=${p.direction} cents=${cents} :: ${e?.message ?? e}` },
698	    }).catch(() => {});
699	  }
700	}
