702	async function runJob(job: Job) {
703	  // The job is already atomically claimed (status RUNNING, attempts incremented)
704	  // by the loop's compare-and-swap before we get here — see the CAS in main().
705	  console.log(`[worker] job ${job.id} ${job.type} server=${job.serverId}`);
706	  try {
707	    await handlers[job.type](job);
708	    await db.job.update({ where: { id: job.id }, data: { status: "DONE" } });
709	    console.log(`[worker] job ${job.id} DONE`);
710	  } catch (e: any) {
711	    const error = `${e?.message ?? e}${e?.body ? ` :: ${e.body}` : ""}`.slice(0, 2000);
712	    console.error(`[worker] job ${job.id} FAILED: ${error}`);
713	    const current = await db.job.findUnique({ where: { id: job.id } });
714	    const retriable = (current?.attempts ?? MAX_ATTEMPTS) < MAX_ATTEMPTS;
715	    await db.job.update({
716	      where: { id: job.id },
717	      data: { status: retriable ? "QUEUED" : "FAILED", error },
718	    });
719	    if (!retriable) {
720	      await reconcileFailedJob(job).catch((err) => console.error(`[worker] reconcile ${job.id} failed`, err));
721	      if (job.serverId) {
722	        const stillExists = await db.server.findUnique({ where: { id: job.serverId } });
723	        if (stillExists) {
724	          await db.server.update({ where: { id: job.serverId }, data: { status: "ERROR" } });
725	        }
726	      }
727	    }
728	  }
729	}
