731	/**
732	 * Recover jobs left RUNNING by a previous worker crash/restart. Without this a
733	 * killed worker leaves a job RUNNING forever, which permanently blocks the
734	 * server's "one in-flight job" guard and strands it in a transitional state.
735	 */
736	async function reapStuckJobs() {
737	  const stuck = await db.job.findMany({ where: { status: "RUNNING" } });
738	  for (const job of stuck) {
739	    const retriable = job.attempts < MAX_ATTEMPTS;
740	    await db.job.update({
741	      where: { id: job.id },
742	      data: { status: retriable ? "QUEUED" : "FAILED", error: retriable ? null : "Worker restarted mid-job" },
743	    });
744	    if (!retriable) {
745	      await reconcileFailedJob(job).catch((err) => console.error(`[worker] reconcile ${job.id} failed`, err));
746	      if (job.serverId) {
747	        const s = await db.server.findUnique({ where: { id: job.serverId } });
748	        if (s && ["PROVISIONING", "REINSTALLING", "DELETING"].includes(s.status)) {
749	          await db.server.update({ where: { id: job.serverId }, data: { status: "ERROR" } });
750	        }
751	      }
752	    }
753	    console.log(`[worker] reaped stuck job ${job.id} (${job.type}) -> ${retriable ? "QUEUED" : "FAILED"}`);
754	  }
755	}
