4	/**
5	 * IPAM — private-IP and SSH-forward-port allocation.
6	 *
7	 * Node-aware: when a `nodeId` is supplied the pool is taken from that Node's
8	 * configured range (`subnetPrefix` / `ipStart` / `ipEnd` / `sshPortStart` /
9	 * `sshPortEnd`). Without a nodeId we fall back to the global env range, which is
10	 * the single-node behaviour this module has always had.
11	 *
12	 * Race safety: `Server.ipAddress` and `Server.sshPort` are UNIQUE columns, so a
13	 * concurrent double-provision must not hand out the same value twice. When the
14	 * caller passes the server it is allocating for, the "find free + claim" pair
15	 * runs inside a single transaction guarded by a Postgres advisory lock, with a
16	 * retry loop on unique-constraint conflicts. Callers that do not pass a server
17	 * id get a best-effort pick plus a short-lived in-process reservation (which
18	 * covers concurrent jobs inside one worker process, the common case).
19	 */
20	
21	const ENV_SUBNET_PREFIX = process.env.NXEON_SUBNET_PREFIX ?? "10.20.0.";
22	const IP_START = Number(process.env.NXEON_IP_START ?? 100);
23	const IP_END = Number(process.env.NXEON_IP_END ?? 250);
24	export const SSH_PORT_START = Number(process.env.NXEON_SSH_PORT_START ?? 20000);
25	export const SSH_PORT_END = Number(process.env.NXEON_SSH_PORT_END ?? 29999);
26	
27	/** Advisory-lock key that serialises IPAM allocation across processes. */
28	const IPAM_LOCK_KEY = 728_144_301;
29	/** How many times we re-pick after losing a unique-constraint race. */
30	const CLAIM_ATTEMPTS = 8;
31	/** How long an unclaimed hand-out is remembered in this process. */
32	const RESERVATION_TTL_MS = 10 * 60_000;
33	
34	export type IpamRange = {
35	  nodeId: string | null;
36	  subnetPrefix: string;
37	  ipStart: number;
38	  ipEnd: number;
39	  sshPortStart: number;
40	  sshPortEnd: number;
41	  bridge: string | null;
42	  natChain: string | null;
43	};
44	
45	const GLOBAL_RANGE: IpamRange = {
46	  nodeId: null,
47	  subnetPrefix: ENV_SUBNET_PREFIX,
48	  ipStart: IP_START,
49	  ipEnd: IP_END,
50	  sshPortStart: SSH_PORT_START,
51	  sshPortEnd: SSH_PORT_END,
52	  bridge: process.env.NXEON_BRIDGE ?? null,
53	  natChain: process.env.NXEON_NAT_CHAIN ?? null,
54	};
55	
56	const num = (v: unknown, fallback: number) =>
57	  typeof v === "number" && Number.isFinite(v) ? v : fallback;
58	
59	/**
60	 * Resolve the pool a node allocates from. Unknown/empty node fields fall back to
61	 * the global env values so a half-configured Node row can never produce an
62	 * empty range.
63	 */
64	export async function ipamRange(nodeId?: string | null): Promise<IpamRange> {
65	  if (!nodeId) return { ...GLOBAL_RANGE };
66	  const node = await db.node.findUnique({
67	    where: { id: nodeId },
68	    select: {
69	      id: true,
70	      subnetPrefix: true,
71	      ipStart: true,
72	      ipEnd: true,
73	      sshPortStart: true,
74	      sshPortEnd: true,
75	      bridge: true,
76	      natChain: true,
77	    },
78	  });
79	  if (!node) return { ...GLOBAL_RANGE };
80	  const prefix = node.subnetPrefix?.trim() || GLOBAL_RANGE.subnetPrefix;
81	  return {
82	    nodeId: node.id,
83	    subnetPrefix: prefix.endsWith(".") ? prefix : `${prefix}.`,
84	    ipStart: num(node.ipStart, GLOBAL_RANGE.ipStart),
85	    ipEnd: num(node.ipEnd, GLOBAL_RANGE.ipEnd),
86	    sshPortStart: num(node.sshPortStart, GLOBAL_RANGE.sshPortStart),
87	    sshPortEnd: num(node.sshPortEnd, GLOBAL_RANGE.sshPortEnd),
88	    bridge: node.bridge ?? GLOBAL_RANGE.bridge,
89	    natChain: node.natChain ?? GLOBAL_RANGE.natChain,
90	  };
91	}
