93	// ---------- in-process reservations ----------
94	
95	const reservations = new Map<string, number>();
96	
97	function isReserved(key: string): boolean {
98	  const until = reservations.get(key);
99	  if (until === undefined) return false;
100	  if (until <= Date.now()) {
101	    reservations.delete(key);
102	    return false;
103	  }
104	  return true;
105	}
106	
107	function reserve(key: string): void {
108	  if (reservations.size > 5000) {
109	    const now = Date.now();
110	    for (const [k, until] of reservations) if (until <= now) reservations.delete(k);
111	  }
112	  reservations.set(key, Date.now() + RESERVATION_TTL_MS);
113	}
114	
115	function isUniqueConflict(e: any): boolean {
116	  return e?.code === "P2002";
117	}
118	
119	type Tx = Prisma.TransactionClient;
120	
121	/**
122	 * Serialise allocators across processes with a transaction-scoped advisory lock
123	 * (auto-released on commit/rollback). Support is probed once OUTSIDE a
124	 * transaction — a failing statement inside an open Postgres transaction would
125	 * abort it, so we never speculatively try it in the hot path.
126	 */
127	let advisoryLocks: boolean | null = null;
128	// Two workarounds baked in:
129	//  - the key is a literal, not a bound parameter: a bound JS number can reach
130	//    Postgres as `numeric` and fail to resolve the ...(bigint) overload;
131	//  - pg_advisory_xact_lock() returns `void`, which Prisma's $queryRaw cannot
132	//    deserialize, so it is wrapped in a subselect that yields an int column.
133	const LOCK_SQL = `SELECT 1 AS locked FROM (SELECT pg_advisory_xact_lock(${IPAM_LOCK_KEY})) _lock`;
134	
135	async function lockIpam(tx: Tx): Promise<void> {
136	  if (advisoryLocks === false) return;
137	  await tx.$queryRawUnsafe(LOCK_SQL);
138	}
139	
140	async function probeAdvisoryLocks(): Promise<void> {
141	  if (advisoryLocks !== null) return;
142	  try {
143	    // Take and immediately release it (xact locks drop at commit). Done once,
144	    // outside the hot path, because a failing statement inside an open
145	    // transaction would abort that transaction.
146	    await db.$transaction(async (tx) => {
147	      await tx.$queryRawUnsafe(LOCK_SQL);
148	    });
149	    advisoryLocks = true;
150	  } catch {
151	    // Not Postgres, or the role lacks permission: the unique-conflict retry
152	    // loop plus in-process reservations remain as the safety net.
153	    advisoryLocks = false;
154	  }
155	}
156	
157	// ---------- IP allocation ----------
158	
159	/**
160	 * Candidate IPs are all `<prefix><n>`, so only servers already sitting in the
161	 * same subnet prefix can conflict — servers on other nodes (different prefix)
162	 * are naturally excluded. We still read the column globally because
163	 * `Server.ipAddress` is globally UNIQUE: skipping a value that another node
164	 * happens to hold is what keeps the insert from blowing up.
165	 */
166	async function pickFreeIp(tx: Tx, range: IpamRange): Promise<string> {
167	  const rows = await tx.server.findMany({
168	    where: { ipAddress: { startsWith: range.subnetPrefix } },
169	    select: { ipAddress: true },
170	  });
171	  const used = new Set(rows.map((r) => r.ipAddress!).filter(Boolean));
172	  for (let i = range.ipStart; i <= range.ipEnd; i++) {
173	    const ip = `${range.subnetPrefix}${i}`;
174	    if (used.has(ip)) continue;
175	    if (isReserved(`ip:${ip}`)) continue;
176	    return ip;
177	  }
178	  throw new Error(
179	    range.nodeId
180	      ? `IP pool exhausted for node ${range.nodeId} (${range.subnetPrefix}${range.ipStart}-${range.ipEnd})`
181	      : "IP pool exhausted"
182	  );
183	}
184	
185	/**
186	 * Allocate a private IP.
187	 *
188	 * @param nodeId          allocate from this Node's configured subnet/range.
189	 * @param claimForServerId when given, the IP is written onto that Server row in
190	 *                         the same transaction, making the allocation atomic.
191	 */
192	export async function allocateIp(
193	  nodeId?: string | null,
194	  claimForServerId?: string | null
195	): Promise<string> {
196	  const range = await ipamRange(nodeId);
197	  await probeAdvisoryLocks();
198	
199	  if (!claimForServerId) {
200	    // No row to claim against: pick + reserve in-process so concurrent jobs in
201	    // this worker cannot be handed the same address.
202	    const ip = await db.$transaction(async (tx) => {
203	      await lockIpam(tx);
204	      return pickFreeIp(tx, range);
205	    });
206	    reserve(`ip:${ip}`);
207	    return ip;
208	  }
209	
210	  let lastErr: unknown;
211	  for (let attempt = 0; attempt < CLAIM_ATTEMPTS; attempt++) {
212	    let ip = "";
213	    try {
214	      ip = await db.$transaction(async (tx) => {
215	        await lockIpam(tx);
216	        const candidate = await pickFreeIp(tx, range);
217	        await tx.server.update({
218	          where: { id: claimForServerId },
219	          data: { ipAddress: candidate },
220	        });
221	        return candidate;
222	      });
223	    } catch (e) {
224	      lastErr = e;
225	      if (isUniqueConflict(e)) {
226	        // Someone beat us to it between pick and claim — skip it and retry.
227	        continue;
228	      }
229	      throw e;
230	    }
231	    reserve(`ip:${ip}`);
232	    return ip;
233	  }
234	  throw new Error(
235	    `IP allocation contended — gave up after ${CLAIM_ATTEMPTS} attempts` +
236	      (lastErr ? `: ${String((lastErr as any)?.message ?? lastErr).slice(0, 160)}` : "")
237	  );
238	}
239	
240	// ---------- SSH forward-port allocation ----------
241	
242	/**
243	 * `Server.sshPort` and `PortForward.publicPort` are both globally UNIQUE, so the
244	 * taken-set is read globally even though the *range* we scan is per-node.
245	 * Node-awareness therefore comes from the range: give each node a disjoint
246	 * sshPortStart/sshPortEnd window and two nodes can never collide.
247	 */
248	async function pickFreePort(tx: Tx, range: IpamRange): Promise<number> {
249	  const [servers, forwards] = await Promise.all([
250	    tx.server.findMany({
251	      where: { sshPort: { gte: range.sshPortStart, lte: range.sshPortEnd } },
252	      select: { sshPort: true },
253	    }),
254	    tx.portForward.findMany({
255	      where: { publicPort: { gte: range.sshPortStart, lte: range.sshPortEnd } },
256	      select: { publicPort: true },
257	    }),
258	  ]);
259	  const used = new Set<number>([
260	    ...servers.map((s) => s.sshPort!).filter((p) => p != null),
261	    ...forwards.map((f) => f.publicPort),
262	  ]);
263	  for (let p = range.sshPortStart; p <= range.sshPortEnd; p++) {
264	    if (used.has(p)) continue;
265	    if (isReserved(`port:${p}`)) continue;
266	    return p;
267	  }
268	  throw new Error(
269	    range.nodeId
270	      ? `SSH port pool exhausted for node ${range.nodeId} (${range.sshPortStart}-${range.sshPortEnd})`
271	      : "SSH port pool exhausted"
272	  );
273	}
274	
275	/**
276	 * Allocate an SSH forward port.
277	 *
278	 * @param nodeId          allocate from this Node's configured port range.
279	 * @param claimForServerId when given, the port is written onto that Server row
280	 *                         in the same transaction, making it atomic.
281	 */
282	export async function allocateSshPort(
283	  nodeId?: string | null,
284	  claimForServerId?: string | null
285	): Promise<number> {
286	  const range = await ipamRange(nodeId);
287	  await probeAdvisoryLocks();
288	
289	  if (!claimForServerId) {
290	    const port = await db.$transaction(async (tx) => {
291	      await lockIpam(tx);
292	      return pickFreePort(tx, range);
293	    });
294	    reserve(`port:${port}`);
295	    return port;
296	  }
297	
298	  let lastErr: unknown;
299	  for (let attempt = 0; attempt < CLAIM_ATTEMPTS; attempt++) {
300	    let port = 0;
301	    try {
302	      port = await db.$transaction(async (tx) => {
303	        await lockIpam(tx);
304	        const candidate = await pickFreePort(tx, range);
305	        await tx.server.update({
306	          where: { id: claimForServerId },
307	          data: { sshPort: candidate },
308	        });
309	        return candidate;
310	      });
311	    } catch (e) {
312	      lastErr = e;
313	      if (isUniqueConflict(e)) continue;
314	      throw e;
315	    }
316	    reserve(`port:${port}`);
317	    return port;
318	  }
319	  throw new Error(
320	    `SSH port allocation contended — gave up after ${CLAIM_ATTEMPTS} attempts` +
321	      (lastErr ? `: ${String((lastErr as any)?.message ?? lastErr).slice(0, 160)}` : "")
322	  );
323	}
324	
325	// ---------- gateway ----------
326	
327	/**
328	 * Gateway for a NAT subnet. Backwards compatible: called with no argument it
329	 * returns the global gateway exactly as before. Pass a Node's `subnetPrefix`
330	 * (or use {@link gatewayIpForNode}) for multi-node correctness.
331	 */
332	export function gatewayIp(subnetPrefix?: string | null): string {
333	  const prefix = subnetPrefix?.trim() || ENV_SUBNET_PREFIX;
334	  return `${prefix.endsWith(".") ? prefix : `${prefix}.`}1`;
335	}
336	
337	/** Async node-aware variant of {@link gatewayIp}. */
338	export async function gatewayIpForNode(nodeId?: string | null): Promise<string> {
339	  const range = await ipamRange(nodeId);
340	  return gatewayIp(range.subnetPrefix);
341	}
