3	const insecureAgent = new Agent({ connect: { rejectUnauthorized: false } });
4	
5	const BASE = process.env.PROXMOX_API_URL ?? "https://127.0.0.1:8006";
6	const NODE = process.env.PROXMOX_NODE ?? "";
7	const TOKEN = `PVEAPIToken=${process.env.PROXMOX_TOKEN_ID}=${process.env.PROXMOX_TOKEN_SECRET}`;
