66	/** Connection details for a specific Node row (see Prisma `Node`). */
67	export type NodeConn = {
68	  apiUrl: string;
69	  pveNode: string;
70	  tokenId: string;
71	  tokenSecret: string;
72	};
73	
74	export type PveClient = {
75	  get: (path: string, params?: Record<string, any>) => Promise<any>;
76	  post: (path: string, params?: Record<string, any>) => Promise<any>;
77	  put: (path: string, params?: Record<string, any>) => Promise<any>;
78	  del: (path: string, params?: Record<string, any>) => Promise<any>;
79	  node: string;
80	  waitForTask: (upid: string, timeoutMs?: number) => Promise<void>;
81	  nextVmid: () => Promise<number>;
82	  vmStatus: (vmid: number) => Promise<any>;
83	};
