85	/** Build a Proxmox client bound to a specific node. Use in the worker for multi-node. */
86	export function pveFor(conn: NodeConn): PveClient {
87	  const token = `PVEAPIToken=${conn.tokenId}=${conn.tokenSecret}`;
88	  const req = (m: "GET" | "POST" | "PUT" | "DELETE", path: string, params?: Record<string, any>) =>
89	    pveRequestTo(conn.apiUrl, token, m, path, params);
90	  const client: PveClient = {
91	    get: (p, params) => req("GET", p, params),
92	    post: (p, params) => req("POST", p, params),
93	    put: (p, params) => req("PUT", p, params),
94	    del: (p, params) => req("DELETE", p, params),
95	    node: conn.pveNode,
96	    async waitForTask(upid: string, timeoutMs = 300_000) {
97	      const start = Date.now();
98	      while (Date.now() - start < timeoutMs) {
99	        const status = await req("GET", `/nodes/${conn.pveNode}/tasks/${encodeURIComponent(upid)}/status`);
100	        if (status.status === "stopped") {
101	          if (status.exitstatus !== "OK") throw new Error(`Proxmox task failed: ${status.exitstatus}`);
102	          return;
103	        }
104	        await new Promise((r) => setTimeout(r, 2000));
105	      }
106	      throw new Error(`Proxmox task timed out: ${upid}`);
107	    },
108	    async nextVmid() {
109	      return Number(await req("GET", "/cluster/nextid"));
110	    },
111	    async vmStatus(vmid: number) {
112	      return req("GET", `/nodes/${conn.pveNode}/qemu/${vmid}/status/current`);
113	    },
114	  };
115	  return client;
116	}
117	
118	export async function waitForTask(upid: string, timeoutMs = 300_000): Promise<void> {
119	  const start = Date.now();
120	  while (Date.now() - start < timeoutMs) {
121	    const status = await pve.get(`/nodes/${NODE}/tasks/${encodeURIComponent(upid)}/status`);
122	    if (status.status === "stopped") {
123	      if (status.exitstatus !== "OK") {
124	        throw new Error(`Proxmox task failed: ${status.exitstatus}`);
125	      }
126	      return;
127	    }
128	    await new Promise((r) => setTimeout(r, 2000));
129	  }
130	  throw new Error(`Proxmox task timed out: ${upid}`);
131	}
