5	const SERVER = process.env.OVH_SERVER_NAME ?? "ns5002569.ip-51-79-162.net";
6	/** Monthly price the customer pays for a dedicated IPv4 (OVH cost ~$2.39 + margin). */
7	export const DEDICATED_IP_PRICE_CENTS = Number(process.env.DEDICATED_IP_PRICE_CENTS ?? 399);
8	/** Keep this many spare IPs in the pool; auto-order/release aims to stay near it. */
