11	/** OVH failover gateway = the host's /24 gateway (…​.254). */
12	export function ovhGateway(): string {
13	  const ip = process.env.PUBLIC_IP ?? "51.79.162.96";
14	  const parts = ip.split(".");
15	  return `${parts[0]}.${parts[1]}.${parts[2]}.254`;
16	}
