18	/**
19	 * Pull additional/failover IPv4 addresses routed to our server from OVH and
20	 * upsert them into the pool. The host's own primary IP is never poolable.
21	 */
22	export async function syncDedicatedIpPool(): Promise<{ imported: number; total: number }> {
23	  if (SANDBOX) return { imported: 0, total: 0 };
24	  if (!ovhConfigured()) return { imported: 0, total: 0 };
25	  const primary = process.env.PUBLIC_IP;
26	  const blocks: string[] = await ovhApi.ips();
27	  let imported = 0;
28	  for (const block of blocks) {
29	    if (block.includes(":")) continue; // IPv6 handled separately
30	    let info: any;
31	    try {
32	      info = await ovhApi.ipInfo(block);
33	    } catch {
34	      continue;
35	    }
36	    if (info?.routedTo?.serviceName !== SERVER) continue;
37	    if (info?.type !== "failover" && info?.type !== "additional") continue; // exclude the primary "dedicated" host IP
38	    // A /32 block is a single usable IP == the block minus the mask.
39	    const address = block.split("/")[0];
40	    if (address === primary) continue;
41	    const existing = await db.dedicatedIp.findUnique({ where: { address } });
42	    if (!existing) {
43	      await db.dedicatedIp.create({ data: { address, ovhBlock: block, status: "FREE" } });
44	      imported++;
45	    }
46	  }
47	  const total = await db.dedicatedIp.count();
48	  return { imported, total };
49	}
