55	/** Find the OVH Virtual MAC currently bound to an IP, if any. */
56	async function findVirtualMacForIp(address: string): Promise<string | null> {
57	  const macs: string[] = await ovh("GET", `/dedicated/server/${SERVER}/virtualMac`).catch(() => []);
58	  for (const m of macs) {
59	    const ips: string[] = await ovh(
60	      "GET",
61	      `/dedicated/server/${SERVER}/virtualMac/${m}/virtualAddress`
62	    ).catch(() => []);
63	    if (ips.includes(address)) return m;
64	  }
65	  return null;
66	}
