68	/**
69	 * Claim a free IP for a server and create its OVH Virtual MAC so the VM can use it.
70	 * Returns the address + virtualMac + gateway, or null if none available.
71	 */
72	export async function allocateDedicatedIp(
73	  serverId: string,
74	  vmid: number
75	): Promise<{ address: string; virtualMac: string; gateway: string } | null> {
76	  if (SANDBOX) {
77	    // Hand out a synthetic dedicated IP without any OVH call or pool mutation.
78	    return { address: sandboxIp(vmid), virtualMac: sandboxMac(vmid), gateway: "198.51.100.254" };
79	  }
80	  if (!ovhConfigured()) return null;
81	  // Atomically claim a FREE ip
82	  const claim = await db.$transaction(async (tx) => {
83	    const ip = await tx.dedicatedIp.findFirst({ where: { status: "FREE" }, orderBy: { createdAt: "asc" } });
84	    if (!ip) return null;
85	    await tx.dedicatedIp.update({ where: { id: ip.id }, data: { status: "PENDING", serverId } });
86	    return ip;
87	  });
88	  if (!claim) return null;
89	
90	  try {
91	    // Reuse an existing vMAC for this IP if one is already bound; else create one.
92	    let mac = await findVirtualMacForIp(claim.address);
93	    if (!mac) {
94	      // Creation is asynchronous (returns a task) — kick it off then poll.
95	      await ovhApi.createVirtualMac(SERVER, claim.address, `nxeon-${vmid}`);
96	      for (let i = 0; i < 40 && !mac; i++) {
97	        await new Promise((r) => setTimeout(r, 3000));
98	        mac = await findVirtualMacForIp(claim.address);
99	      }
100	    }
101	    if (!mac) throw new Error("Virtual MAC not bound after creation (OVH task still pending)");
102	    await db.dedicatedIp.update({ where: { id: claim.id }, data: { status: "ASSIGNED", virtualMac: mac } });
103	    return { address: claim.address, virtualMac: mac, gateway: ovhGateway() };
104	  } catch (e) {
105	    // Roll the claim back to FREE on failure
106	    await db.dedicatedIp.update({ where: { id: claim.id }, data: { status: "FREE", serverId: null, virtualMac: null } });
107	    throw e;
108	  }
109	}
