161	/**
162	 * VOLUME_DETACH — detach the disk from the VM (Proxmox moves it to an "unused"
163	 * entry, preserving the data). The volume stays pinned to this server so it can
164	 * be re-attached here later.
165	 */
166	export async function volumeDetach(job: Job): Promise<void> {
167	  const volume = await loadVolume(job);
168	  const server = volume.server;
169	
170	  if (SANDBOX) {
171	    await db.volume.update({ where: { id: volume.id }, data: { status: "DETACHED" } });
172	    if (server) {
173	      await notify(
174	        volume.userId,
175	        `Volume "${volume.name}" detached from ${server.hostname}`,
176	        "The volume and its data are preserved and can be re-attached (sandbox).",
177	        "/dashboard/volumes"
178	      );
179	    }
180	    return;
181	  }
182	
183	  if (server?.vmid && volume.diskName) {
184	    const { conn } = await nodeFor(server);
185	    const config = (await conn.get(`/nodes/${conn.node}/qemu/${server.vmid}/config`)) as Record<string, any>;
186	    const key = keyForVolid(config, volume.diskName);
187	    if (key && key.startsWith("scsi")) {
188	      await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/config`, { delete: key });
189	    }
190	  }
191	
192	  await db.volume.update({ where: { id: volume.id }, data: { status: "DETACHED" } });
193	  if (server) {
194	    await notify(
195	      volume.userId,
196	      `Volume "${volume.name}" detached from ${server.hostname}`,
197	      "The volume and its data are preserved and can be re-attached to the same server.",
198	      "/dashboard/volumes"
199	    );
200	  }
201	}
202	
203	/**
204	 * VOLUME_DELETE — detach (if attached) then permanently destroy the underlying
205	 * disk, and remove the Volume row.
206	 */
207	export async function volumeDelete(job: Job): Promise<void> {
208	  const volume = await loadVolume(job);
209	  const server = volume.server;
210	
211	  if (SANDBOX) {
212	    await db.volume.delete({ where: { id: volume.id } });
213	    await notify(volume.userId, `Volume "${volume.name}" deleted`, undefined, "/dashboard/volumes");
214	    return;
215	  }
216	
217	  if (server?.vmid && volume.diskName) {
218	    const { conn } = await nodeFor(server);
219	    try {
220	      let config = (await conn.get(`/nodes/${conn.node}/qemu/${server.vmid}/config`)) as Record<string, any>;
221	      let key = keyForVolid(config, volume.diskName);
222	
223	      // If still mounted, detach to an "unused" entry first.
224	      if (key && key.startsWith("scsi")) {
225	        await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/config`, { delete: key });
226	        config = (await conn.get(`/nodes/${conn.node}/qemu/${server.vmid}/config`)) as Record<string, any>;
227	        key = keyForVolid(config, volume.diskName);
228	      }
229	      // Deleting an "unused" entry destroys the underlying disk.
230	      if (key) {
231	        await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/config`, { delete: key });
232	      }
233	    } catch (e: any) {
234	      const msg = String(e?.body ?? e?.message ?? e);
235	      if (!msg.includes("does not exist")) throw e;
236	    }
237	  }
238	
239	  await db.volume.delete({ where: { id: volume.id } });
240	  await notify(volume.userId, `Volume "${volume.name}" deleted`, undefined, "/dashboard/volumes");
241	}
