61	// ---- Timeouts -------------------------------------------------------------
62	const CONNECT_TIMEOUT_MS = 20_000;
63	const SETUP_TIMEOUT_MS = 60_000; // installs, mkdir, small writes
64	const TRANSFER_TIMEOUT_MS = Number(process.env.MIGRATE_EXEC_TIMEOUT_MS ?? 45 * 60_000); // rsync/dump
65	
66	// ---- Strict allowlist validators (throw on any violation) -----------------
67	// Charsets below are deliberately shell-inert: no quotes, spaces, metachars, or
68	// newlines. Validated values are therefore safe to interpolate into a command.
69	const HOSTNAME_RE = /^[A-Za-z0-9]([A-Za-z0-9.-]{0,251}[A-Za-z0-9])?$/;
70	const IPV4_RE = /^(25[0-5]|2[0-4]\d|1?\d?\d)(\.(25[0-5]|2[0-4]\d|1?\d?\d)){3}$/;
71	const IPV6_RE = /^[0-9A-Fa-f:]{2,45}$/;
72	const USER_RE = /^[a-z_][a-z0-9_-]{0,31}$/;
73	const IDENT_RE = /^[A-Za-z0-9_]{1,64}$/; // DB name / DB user
74	const PATH_RE = /^\/[A-Za-z0-9._/-]{0,255}$/; // absolute path, safe charset
75	
76	function assert(cond: unknown, msg: string): asserts cond {
77	  if (!cond) throw new Error(msg);
78	}
79	
80	function validHost(h: string): boolean {
81	  return typeof h === "string" && (HOSTNAME_RE.test(h) || IPV4_RE.test(h) || IPV6_RE.test(h));
82	}
83	
84	function validPath(p: string): boolean {
85	  return typeof p === "string" && PATH_RE.test(p) && !p.includes("..") && !p.includes("//");
86	}
87	
88	/** dirname of a validated absolute path (both inputs/outputs are shell-inert). */
89	function parentDir(p: string): string {
90	  const i = p.lastIndexOf("/");
91	  return i <= 0 ? "/" : p.slice(0, i);
92	}
