94	// ---- SSH plumbing ---------------------------------------------------------
95	function execRemote(
96	  conn: Client,
97	  cmd: string,
98	  timeoutMs: number
99	): Promise<{ code: number; stdout: string; stderr: string }> {
100	  return new Promise((resolve, reject) => {
101	    conn.exec(cmd, (err, stream: ClientChannel) => {
102	      if (err) return reject(err);
103	      let stdout = "";
104	      let stderr = "";
105	      const timer = setTimeout(() => {
106	        try {
107	          stream.close();
108	        } catch {
109	          /* ignore */
110	        }
111	        reject(new Error("remote command timed out"));
112	      }, timeoutMs);
113	      stream
114	        .on("close", (code: number) => {
115	          clearTimeout(timer);
116	          resolve({ code: code ?? 0, stdout, stderr });
117	        })
118	        .on("data", (d: Buffer) => (stdout += d.toString("utf8")))
119	        .stderr.on("data", (d: Buffer) => (stderr += d.toString("utf8")));
120	    });
121	  });
122	}
123	
124	/**
125	 * Run a remote command and stream `input` into its STDIN. Used to write a secret
126	 * into a file on the far side (`cat > file`) without the secret ever appearing as
127	 * a command-line argument.
128	 */
129	function execRemoteInput(
130	  conn: Client,
131	  cmd: string,
132	  input: string,
133	  timeoutMs: number
134	): Promise<{ code: number; stdout: string; stderr: string }> {
135	  return new Promise((resolve, reject) => {
136	    conn.exec(cmd, (err, stream: ClientChannel) => {
137	      if (err) return reject(err);
138	      let stdout = "";
139	      let stderr = "";
140	      const timer = setTimeout(() => {
141	        try {
142	          stream.close();
143	        } catch {
144	          /* ignore */
145	        }
146	        reject(new Error("remote command timed out"));
147	      }, timeoutMs);
148	      stream
149	        .on("close", (code: number) => {
150	          clearTimeout(timer);
151	          resolve({ code: code ?? 0, stdout, stderr });
152	        })
153	        .on("data", (d: Buffer) => (stdout += d.toString("utf8")))
154	        .stderr.on("data", (d: Buffer) => (stderr += d.toString("utf8")));
155	      stream.end(input);
156	    });
157	  });
158	}
159	
160	/** Write bytes to a remote file over SFTP with a fixed 0600 mode (no shell). */
161	function sftpWrite(sftp: SFTPWrapper, path: string, content: string): Promise<void> {
162	  return new Promise((resolve, reject) => {
163	    const ws = sftp.createWriteStream(path, { mode: 0o600 });
164	    ws.on("close", () => resolve());
165	    ws.on("error", (e: Error) => reject(e));
166	    ws.end(Buffer.from(content, "utf8"));
167	  });
168	}
169	
170	function connectTarget(server: TargetServer): Promise<{ conn: Client; sftp: SFTPWrapper }> {
171	  return new Promise((resolve, reject) => {
172	    const target = connectionTarget(server as any);
173	    if (!target) return reject(new Error("target server is not reachable yet — connection details are pending"));
174	    if (!server.rootPassword) return reject(new Error("target server has no root password on record"));
175	    const conn = new Client();
176	    conn.on("ready", () => {
177	      conn.sftp((err, sftp) => {
178	        if (err) return reject(err);
179	        resolve({ conn, sftp });
180	      });
181	    });
182	    conn.on("error", (e) => reject(e instanceof Error ? e : new Error(String(e))));
183	    conn.connect({
184	      host: target.host,
185	      port: target.port,
186	      username: "root",
187	      password: server.rootPassword,
188	      readyTimeout: CONNECT_TIMEOUT_MS,
189	    });
190	  });
191	}
