195	/**
196	 * Perform a real migration. Throws on any fatal error (migrate.ts records it as
197	 * FAILED and scrubs stored secrets). Validated inputs are shell-inert; secrets
198	 * flow only through SFTP writes and command STDIN.
199	 */
200	export async function runRealMigration(input: RealMigrationInput): Promise<void> {
201	  const { migration, target, items, report } = input;
202	  assert(target, "target server row not found");
203	
204	  // ---- 1. Validate EVERY non-secret input up front (fail closed) ----------
205	  const host = migration.sourceHost;
206	  const port = migration.sourcePort;
207	  const user = migration.sourceUser;
208	  assert(validHost(host), "source host is not a valid hostname or IP address");
209	  assert(Number.isInteger(port) && port >= 1 && port <= 65535, "source SSH port is out of range");
210	  assert(USER_RE.test(user), "source username contains unsupported characters");
211	
212	  const paths = (items.paths ?? []).map((p) => p.trim()).filter(Boolean);
213	  for (const p of paths) assert(validPath(p), `unsupported file path: ${p}`);
214	
215	  const databases = items.databases ?? [];
216	  for (const d of databases) {
217	    assert(d.engine === "mysql" || d.engine === "postgres", `unsupported database engine: ${d.engine}`);
218	    assert(IDENT_RE.test(d.name), `unsupported database name: ${d.name}`);
219	    assert(IDENT_RE.test(d.user), `unsupported database user: ${d.user}`);
220	  }
221	
222	  assert(paths.length || databases.length, "nothing selected to migrate");
223	
224	  // ---- 2. Decrypt secrets IN MEMORY ONLY ----------------------------------
225	  const sshPass = decryptSecret(migration.sourcePasswordEnc);
226	  assert(sshPass, "source SSH password is missing or could not be decrypted");
227	
228	  // ---- 3. Connect to the TARGET (our own server) --------------------------
229	  await report(10, "Connecting…", `Connecting to your Nxeon server to prepare the transfer.`);
230	  const { conn, sftp } = await connectTarget(target!);
231	
232	  // Per-migration work dir on the target (migration.id is a cuid — alphanumeric).
233	  const work = `/root/nxeon-migrations/${migration.id}`;
234	  const passFile = `${work}/ssh.pass`;
235	  const knownHosts = `${work}/known_hosts`;
236	  // SSH options for every source connection: force password auth, TOFU host key.
237	  const sshOpts =
238	    `-p ${port} -o StrictHostKeyChecking=accept-new -o UserKnownHostsFile=${knownHosts} ` +
239	    `-o ConnectTimeout=25 -o PreferredAuthentications=password -o PubkeyAuthentication=no`;
240	  const srcSpec = `${user}@${host}`;
241	
242	  try {
243	    // ---- 4. Prepare the target: tools + work dir + secret file -------------
244	    await report(14, "Preparing…", "Ensuring transfer tools (rsync, sshpass) are present on the target.");
245	    // Fixed command — no user input. Best-effort across apt/dnf/yum; ignore if present.
246	    await execRemote(
247	      conn,
248	      `command -v rsync >/dev/null 2>&1 && command -v sshpass >/dev/null 2>&1 || ` +
249	        `{ (apt-get update -y && apt-get install -y rsync sshpass) || (dnf install -y rsync sshpass) || (yum install -y rsync sshpass); }`,
250	      SETUP_TIMEOUT_MS
251	    );
252	    const tools = await execRemote(conn, `command -v rsync && command -v sshpass`, SETUP_TIMEOUT_MS);
253	    assert(tools.code === 0, "could not install rsync/sshpass on the target server");
254	
255	    await execRemote(
256	      conn,
257	      `mkdir -p ${work}/files ${work}/dumps && chmod 700 ${work} && touch ${knownHosts} && chmod 600 ${knownHosts}`,
258	      SETUP_TIMEOUT_MS
259	    );
260	
261	    // Write the source SSH password to a 0600 file over SFTP (never a shell arg).
262	    await sftpWrite(sftp, passFile, sshPass);
263	
264	    // ---- 5. Files: rsync-pull each path into the staging dir ---------------
265	    if (paths.length) {
266	      await report(30, "Copying files…", `Copying ${paths.length} path(s) from ${srcSpec}.`);
267	      let idx = 0;
268	      for (const p of paths) {
269	        idx++;
270	        const destParent = `${work}/files${parentDir(p)}`;
271	        await execRemote(conn, `mkdir -p ${destParent}`, SETUP_TIMEOUT_MS);
272	        const pct = 30 + Math.round((idx / paths.length) * 30); // 30 → 60
273	        await report(pct, "Copying files…", `  rsync ${p}`);
274	        const r = await execRemote(
275	          conn,
276	          `sshpass -f ${passFile} rsync -az --numeric-ids --timeout=1200 -e 'ssh ${sshOpts}' ${srcSpec}:${p} ${destParent}/`,
277	          TRANSFER_TIMEOUT_MS
278	        );
279	        if (r.code !== 0) {
280	          const tail = (r.stderr || r.stdout || "").split("\n").slice(-3).join(" ").slice(0, 300);
281	          throw new Error(`file copy failed for ${p}: ${tail || `rsync exit ${r.code}`}`);
282	        }
283	      }
284	    }
285	
286	    // ---- 6. Databases: dump each into the staging dir ---------------------
287	    if (databases.length) {
288	      await report(65, "Dumping databases…", `Dumping ${databases.length} database(s) from the source.`);
289	      let idx = 0;
290	      for (const d of databases) {
291	        idx++;
292	        const dbPass = decryptSecret(d.passEnc);
293	        assert(dbPass, `database password for "${d.name}" is missing or could not be decrypted`);
294	        const pct = 65 + Math.round((idx / databases.length) * 25); // 65 → 90
295	        await report(pct, "Dumping databases…", `  ${d.engine === "postgres" ? "pg_dump" : "mysqldump"} ${d.name}`);
296	
297	        if (d.engine === "mysql") {
298	          const srcCnf = `.nxmig-${migration.id}-${idx}.cnf`;
299	          const dumpFile = `${work}/dumps/mysql-${d.name}.sql`;
300	          // Write a defaults-extra-file on the SOURCE via STDIN (password never an argv token).
301	          const cnfBody = `[client]\nuser=${d.user}\npassword=${dbPass}\nhost=127.0.0.1\n`;
302	          const w = await execRemoteInput(
303	            conn,
304	            `sshpass -f ${passFile} ssh ${sshOpts} ${srcSpec} 'umask 077; cat > ${srcCnf}'`,
305	            cnfBody,
306	            SETUP_TIMEOUT_MS
307	          );
308	          assert(w.code === 0, `could not stage MySQL credentials for "${d.name}"`);
309	          // Dump on source, stream to a file on the target. mysqldump reads the
310	          // password from the cnf file — no secret on the command line.
311	          const r = await execRemote(
312	            conn,
313	            `sshpass -f ${passFile} ssh ${sshOpts} ${srcSpec} ` +
314	              `'mysqldump --defaults-extra-file=${srcCnf} --single-transaction --routines --triggers --databases ${d.name}' > ${dumpFile}`,
315	            TRANSFER_TIMEOUT_MS
316	          );
317	          // Always remove the staged credentials file on the source.
318	          await execRemote(conn, `sshpass -f ${passFile} ssh ${sshOpts} ${srcSpec} 'rm -f ${srcCnf}'`, SETUP_TIMEOUT_MS).catch(() => {});
319	          if (r.code !== 0) {
320	            const tail = (r.stderr || "").split("\n").slice(-3).join(" ").slice(0, 300);
321	            throw new Error(`mysqldump failed for ${d.name}: ${tail || `exit ${r.code}`}`);
322	          }
323	        } else {
324	          const srcPgpass = `.nxmig-${migration.id}-${idx}.pgpass`;
325	          const dumpFile = `${work}/dumps/postgres-${d.name}.sql`;
326	          // .pgpass line: host:port:database:username:password (host/port/db/user validated).
327	          const pgpassBody = `127.0.0.1:*:${d.name}:${d.user}:${dbPass}\n`;
328	          const w = await execRemoteInput(
329	            conn,
330	            `sshpass -f ${passFile} ssh ${sshOpts} ${srcSpec} 'umask 077; cat > ${srcPgpass}'`,
331	            pgpassBody,
332	            SETUP_TIMEOUT_MS
333	          );
334	          assert(w.code === 0, `could not stage Postgres credentials for "${d.name}"`);
335	          // PGPASSFILE points pg_dump at the file — its value is a validated path,
336	          // not a secret. The password lives only inside the file.
337	          const r = await execRemote(
338	            conn,
339	            `sshpass -f ${passFile} ssh ${sshOpts} ${srcSpec} ` +
340	              `'PGPASSFILE=$HOME/${srcPgpass} pg_dump -h 127.0.0.1 -U ${d.user} ${d.name}' > ${dumpFile}`,
341	            TRANSFER_TIMEOUT_MS
342	          );
343	          await execRemote(conn, `sshpass -f ${passFile} ssh ${sshOpts} ${srcSpec} 'rm -f ${srcPgpass}'`, SETUP_TIMEOUT_MS).catch(() => {});
344	          if (r.code !== 0) {
345	            const tail = (r.stderr || "").split("\n").slice(-3).join(" ").slice(0, 300);
346	            throw new Error(`pg_dump failed for ${d.name}: ${tail || `exit ${r.code}`}`);
347	          }
348	        }
349	      }
350	    }
351	
352	    await report(94, "Finalising…", `Transfer complete. Files staged under ${work}/files, database dumps under ${work}/dumps.`);
353	  } finally {
354	    // ---- 7. Scrub the SSH password file from the target, always -----------
355	    await execRemote(conn, `shred -u ${passFile} 2>/dev/null || rm -f ${passFile}`, SETUP_TIMEOUT_MS).catch(() => {});
356	    try {
357	      conn.end();
358	    } catch {
359	      /* best-effort */
360	    }
361	  }
362	}
