364	/** Where migrated data lands on the target, for the completion notice. */
365	export function migrationWorkDir(migrationId: string): string {
366	  return `/root/nxeon-migrations/${migration_id_safe(migrationId)}`;
367	}
368	
369	function migration_id_safe(id: string): string {
370	  return /^[A-Za-z0-9_-]{1,64}$/.test(id) ? id : "invalid";
371	}
