7	/**
8	 * SSL certificate issuance handler (SSL_ISSUE).
9	 *
10	 * `worker/index.ts` owns the job loop and the `handlers` map; wire this in there:
11	 *   SSL_ISSUE: sslIssue,
12	 *
13	 * Ownership + domain validation are enforced at enqueue time
14	 * (lib/actions-ssl.ts), so this handler trusts `payload.certId`.
15	 *
16	 * SAFETY: actually issuing a Let's Encrypt cert means SSHing to the customer's
17	 * VM and running certbot against a live, DNS-pointed domain. That is a real,
18	 * side-effecting operation, so it is DISABLED by default. The real path only
19	 * runs when we're NOT in SANDBOX and ENABLE_REAL_SSL === "1"; otherwise this
20	 * handler always takes the simulated-success branch (which is also what
21	 * SANDBOX/staging requires) and no SSH is ever opened.
22	 */
23	
24	/** A Let's Encrypt certificate is valid for 90 days. */
25	const CERT_LIFETIME_MS = 90 * 86400_000;
26	
27	/**
28	 * ACME account / contact email passed to certbot (`-m`). Let's Encrypt uses it
29	 * for expiry warnings. Override with CERTBOT_EMAIL; falls back to a constant.
30	 */
31	const CERTBOT_EMAIL = process.env.CERTBOT_EMAIL || "ssl-admin@nxeon.local";
32	
33	/** Overall SSH connect timeout, and per-certbot-command timeout. */
34	const SSH_CONNECT_TIMEOUT_MS = 15_000;
35	const CERTBOT_TIMEOUT_MS = 120_000;
36	/** Shorter budget for the quick pre-flight/install probes. */
37	const PROBE_TIMEOUT_MS = 60_000;
38	
39	async function notify(userId: string, title: string, body?: string, href?: string) {
40	  try {
41	    await db.notification.create({ data: { userId, title, body, href } });
42	  } catch (e) {
43	    console.error("[ssl] notify failed", e);
44	  }
45	}
46	
47	// ----------------------------------------------------------------------------
48	// Real issuance path (SSH + certbot). Only reachable when
49	// `!SANDBOX && ENABLE_REAL_SSL === "1"` — see the guard in sslIssue().
50	// ----------------------------------------------------------------------------
51	
52	type SshResult = { code: number | null; stdout: string; stderr: string };
53	
54	/**
55	 * Single-quote a value for safe interpolation into a POSIX shell command.
56	 * We already restrict the domain to a strict charset below, but everything that
57	 * reaches a remote shell is quoted defensively regardless.
58	 */
59	function shellQuote(s: string): string {
60	  return `'${s.replace(/'/g, `'\\''`)}'`;
61	}
62	
63	/** Domains must look like real hostnames before we hand them to certbot. */
64	function assertSafeDomain(domain: string): void {
65	  if (!/^(?=.{1,253}$)([a-zA-Z0-9-]{1,63}\.)+[a-zA-Z]{2,63}$/.test(domain)) {
66	    throw new Error(`Refusing to issue for an unexpected domain: ${domain}`);
67	  }
68	}
69	
70	/**
71	 * Run one command on an already-connected ssh2 client, capturing stdout/stderr
72	 * and the exit code. Rejects on transport error or if the command exceeds
73	 * `timeoutMs` (the channel is torn down so a hung certbot can't wedge the worker).
74	 */
75	function sshExec(conn: SshClient, command: string, timeoutMs: number): Promise<SshResult> {
76	  return new Promise((resolve, reject) => {
77	    conn.exec(command, (err, stream) => {
78	      if (err) return reject(err);
79	      let stdout = "";
80	      let stderr = "";
81	      let settled = false;
82	      const timer = setTimeout(() => {
83	        if (settled) return;
84	        settled = true;
85	        try {
86	          stream.close();
87	        } catch {
88	          /* best effort */
89	        }
90	        reject(new Error(`Command timed out after ${Math.round(timeoutMs / 1000)}s`));
91	      }, timeoutMs);
92	
93	      stream
94	        .on("close", (code: number | null) => {
95	          if (settled) return;
96	          settled = true;
97	          clearTimeout(timer);
98	          resolve({ code, stdout, stderr });
99	        })
100	        .on("data", (d: Buffer) => {
101	          stdout += d.toString("utf8");
102	        })
103	        .stderr.on("data", (d: Buffer) => {
104	          stderr += d.toString("utf8");
105	        });
106	    });
107	  });
108	}
109	
110	/** Open an ssh2 connection to a server, run `fn`, and always end the connection. */
111	async function withSsh<T>(
112	  target: { host: string; port: number },
113	  password: string,
114	  fn: (conn: SshClient) => Promise<T>
115	): Promise<T> {
116	  const conn = new SshClient();
117	  await new Promise<void>((resolve, reject) => {
118	    const timer = setTimeout(() => {
119	      try {
120	        conn.end();
121	      } catch {
122	        /* best effort */
123	      }
124	      reject(new Error(`SSH connect timed out after ${Math.round(SSH_CONNECT_TIMEOUT_MS / 1000)}s`));
125	    }, SSH_CONNECT_TIMEOUT_MS);
126	    conn
127	      .on("ready", () => {
128	        clearTimeout(timer);
129	        resolve();
130	      })
131	      .on("error", (e) => {
132	        clearTimeout(timer);
133	        reject(e);
134	      })
135	      .connect({
136	        host: target.host,
137	        port: target.port,
138	        username: "root",
139	        password,
140	        readyTimeout: SSH_CONNECT_TIMEOUT_MS,
141	      });
142	  });
143	  try {
144	    return await fn(conn);
145	  } finally {
146	    try {
147	      conn.end();
148	    } catch {
149	      /* best effort */
150	    }
151	  }
152	}
