154	/**
155	 * Really issue a Let's Encrypt certificate for `cert.domain` by SSHing into the
156	 * customer's own VM (same host/port/root-password derivation as lib/sftp) and
157	 * driving certbot in --standalone mode. Throws on any failure so the caller's
158	 * catch marks the cert FAILED with the reason.
159	 *
160	 * Steps on the customer VM:
161	 *   1. Detect the package manager (apt-get / dnf) and ensure `certbot` exists,
162	 *      installing it if missing.
163	 *   2. Confirm TCP port 80 is free (standalone binds it for the HTTP-01
164	 *      challenge) — surface a clear error otherwise.
165	 *   3. certbot certonly --standalone -n --agree-tos -m <email> -d <domain>.
166	 *   4. Read the real notAfter from the issued fullchain via `openssl x509
167	 *      -enddate`, falling back to now+90d if that can't be parsed.
168	 *
169	 * Returns the issuedAt/expiresAt to persist.
170	 */
171	async function issueRealCertificate(
172	  cert: SslCertificate
173	): Promise<{ issuedAt: Date; expiresAt: Date }> {
174	  const domain = cert.domain;
175	  assertSafeDomain(domain);
176	
177	  if (!cert.serverId) {
178	    throw new Error("Certificate is not attached to a server.");
179	  }
180	
181	  // Load exactly the fields connectionTarget()/SSH need (mirrors lib/sftp usage).
182	  const server = await db.server.findUnique({
183	    where: { id: cert.serverId },
184	    select: {
185	      id: true,
186	      rootPassword: true,
187	      sshPort: true,
188	      dedicatedIp: { select: { address: true } },
189	    },
190	  });
191	  if (!server) throw new Error(`Server ${cert.serverId} not found.`);
192	
193	  const target = connectionTarget(server as SftpServer);
194	  if (!target) {
195	    throw new Error("Server is not reachable yet — connection details are pending.");
196	  }
197	  if (!server.rootPassword) throw new Error("Server has no root password set.");
198	
199	  const qDomain = shellQuote(domain);
200	  const qEmail = shellQuote(CERTBOT_EMAIL);
201	
202	  return withSsh(target, server.rootPassword, async (conn) => {
203	    // 1. Ensure certbot is present. `command -v` is portable; install only if missing.
204	    const have = await sshExec(conn, "command -v certbot >/dev/null 2>&1 && echo yes || echo no", PROBE_TIMEOUT_MS);
205	    if (have.stdout.trim() !== "yes") {
206	      // Pick the installer from whichever package manager exists.
207	      const pm = await sshExec(
208	        conn,
209	        "if command -v apt-get >/dev/null 2>&1; then echo apt; " +
210	          "elif command -v dnf >/dev/null 2>&1; then echo dnf; else echo none; fi",
211	        PROBE_TIMEOUT_MS
212	      );
213	      const which = pm.stdout.trim();
214	      let installCmd: string;
215	      if (which === "apt") {
216	        installCmd = "DEBIAN_FRONTEND=noninteractive apt-get update -y && apt-get install -y certbot";
217	      } else if (which === "dnf") {
218	        installCmd = "dnf install -y certbot";
219	      } else {
220	        throw new Error("No supported package manager (apt-get/dnf) found to install certbot.");
221	      }
222	      const inst = await sshExec(conn, installCmd, CERTBOT_TIMEOUT_MS);
223	      if (inst.code !== 0) {
224	        throw new Error(`certbot install failed: ${(inst.stderr || inst.stdout).trim().slice(0, 300)}`);
225	      }
226	      // Re-check that certbot is now on PATH.
227	      const recheck = await sshExec(conn, "command -v certbot >/dev/null 2>&1 && echo yes || echo no", PROBE_TIMEOUT_MS);
228	      if (recheck.stdout.trim() !== "yes") {
229	        throw new Error("certbot still not available after install.");
230	      }
231	    }
232	
233	    // 2. Standalone needs port 80. If something is already listening, bail with a
234	    //    clear message rather than letting certbot fail cryptically. (We default to
235	    //    --standalone; --webroot would only be used if a docroot were known.)
236	    const portCheck = await sshExec(
237	      conn,
238	      "ss -ltnH 'sport = :80' 2>/dev/null | head -n1 || true",
239	      PROBE_TIMEOUT_MS
240	    );
241	    if (portCheck.stdout.trim().length > 0) {
242	      throw new Error(
243	        "Port 80 is in use by another service; free it (or configure webroot issuance) before requesting a standalone certificate."
244	      );
245	    }
246	
247	    // 3. Issue. --standalone spins up certbot's own HTTP-01 responder on :80.
248	    const certbotCmd =
249	      `certbot certonly --standalone -n --agree-tos -m ${qEmail} -d ${qDomain}`;
250	    const run = await sshExec(conn, certbotCmd, CERTBOT_TIMEOUT_MS);
251	    const combined = `${run.stdout}\n${run.stderr}`;
252	    // certbot exits 0 on success (including "Certificate not yet due for renewal").
253	    const succeeded =
254	      run.code === 0 &&
255	      /Congratulations|Successfully received certificate|not yet due for renewal|Certificate is saved/i.test(combined);
256	    if (!succeeded) {
257	      throw new Error(`certbot failed: ${combined.trim().slice(0, 400)}`);
258	    }
259	
260	    // 4. Prefer the real notAfter from the issued chain; fall back to now+90d.
261	    const now = new Date();
262	    let expiresAt = new Date(now.getTime() + CERT_LIFETIME_MS);
263	    const live = `/etc/letsencrypt/live/${domain}/fullchain.pem`;
264	    const enddate = await sshExec(
265	      conn,
266	      `openssl x509 -enddate -noout -in ${shellQuote(live)} 2>/dev/null || true`,
267	      PROBE_TIMEOUT_MS
268	    );
269	    const m = enddate.stdout.match(/notAfter=(.+)/);
270	    if (m) {
271	      const parsed = new Date(m[1].trim());
272	      if (!Number.isNaN(parsed.getTime())) expiresAt = parsed;
273	    }
274	
275	    return { issuedAt: now, expiresAt };
276	  });
277	}
