279	export async function sslIssue(job: Job): Promise<void> {
280	  const payload = (job.payload ?? {}) as { certId?: string };
281	  if (!payload.certId) throw new Error("ssl job: missing certId");
282	
283	  const cert = await db.sslCertificate.findUnique({ where: { id: payload.certId } });
284	  if (!cert) throw new Error(`SslCertificate ${payload.certId} not found`);
285	
286	  // Mark in-flight so the UI shows "issuing" while we work.
287	  await db.sslCertificate.update({ where: { id: cert.id }, data: { status: "ISSUING" } });
288	
289	  try {
290	    // ---------------------------------------------------------------------
291	    // Real issuance path (SSH + certbot). Guarded so it can never run by
292	    // accident: it happens ONLY when ENABLE_REAL_SSL is explicitly set AND we
293	    // are not in SANDBOX. In every other case we fall through to the simulated
294	    // success below (the default, and what SANDBOX/staging requires).
295	    //
296	    // The real path (issueRealCertificate) SSHes into the customer's own VM —
297	    // host/port/root/password derived exactly like lib/sftp — and runs:
298	    //   certbot certonly --standalone -n --agree-tos -m <email> -d <domain>
299	    // installing certbot first if needed and reading the real notAfter back.
300	    // ---------------------------------------------------------------------
301	    const realIssuanceEnabled = !SANDBOX && process.env.ENABLE_REAL_SSL === "1";
302	    if (realIssuanceEnabled) {
303	      const { issuedAt, expiresAt } = await issueRealCertificate(cert);
304	      await db.sslCertificate.update({
305	        where: { id: cert.id },
306	        data: { status: "ACTIVE", issuedAt, expiresAt, lastError: null },
307	      });
308	      await notify(
309	        cert.userId,
310	        `SSL certificate issued for ${cert.domain}`,
311	        "Your Let's Encrypt certificate is active.",
312	        "/dashboard/ssl"
313	      );
314	      return;
315	    }
316	
317	    // Default: simulated success (SANDBOX-safe, no SSH, no certbot).
318	    const now = new Date();
319	    await db.sslCertificate.update({
320	      where: { id: cert.id },
321	      data: {
322	        status: "ACTIVE",
323	        issuedAt: now,
324	        expiresAt: new Date(now.getTime() + CERT_LIFETIME_MS),
325	        lastError: null,
326	      },
327	    });
328	    await notify(
329	      cert.userId,
330	      `SSL certificate issued for ${cert.domain}`,
331	      "Your Let's Encrypt certificate is active and valid for 90 days (sandbox).",
332	      "/dashboard/ssl"
333	    );
334	  } catch (e: any) {
335	    const reason = String(e?.message ?? e).slice(0, 500);
336	    await db.sslCertificate.update({
337	      where: { id: cert.id },
338	      data: { status: "FAILED", lastError: reason },
339	    });
340	    await notify(
341	      cert.userId,
342	      `SSL certificate failed for ${cert.domain}`,
343	      reason.slice(0, 200),
344	      "/dashboard/ssl"
345	    );
346	  }
347	}
