6	/**
7	 * Self-service backup restore handler.
8	 *
9	 * Restores a selected vzdump archive back onto the server's existing VM via the
10	 * Proxmox API: stop -> restore (force overwrite) -> start. Ownership and archive
11	 * validation are enforced at enqueue time (`lib/actions-server-ops.ts`), so this
12	 * handler trusts the `volid` in the job payload.
13	 *
14	 * NOTE: `worker/index.ts` owns the job loop and its `handlers` map; wire this in
15	 * there as `BACKUP_RESTORE: backupRestore`.
16	 */
17	
18	async function loadServer(serverId: string) {
19	  const server = await db.server.findUnique({
20	    where: { id: serverId },
21	    include: { node: true },
22	  });
23	  if (!server) throw new Error(`Server ${serverId} not found`);
24	  return server;
25	}
