27	/** Resolve a Proxmox client for the server's node (mirrors worker/index.ts). */
28	async function nodeFor(server: any) {
29	  const n =
30	    server.node ??
31	    (await db.node.findFirst({ where: { isPrimary: true } })) ??
32	    (await db.node.findFirst({ where: { enabled: true } }));
33	  if (!n) {
34	    return {
35	      get: pve.get,
36	      post: pve.post,
37	      put: pve.put,
38	      del: pve.del,
39	      node: envNode,
40	      waitForTask,
41	      nextVmid,
42	      vmStatus: (v: number) => pve.get(`/nodes/${envNode}/qemu/${v}/status/current`),
43	    } as any;
44	  }
45	  return pveFor({ apiUrl: n.apiUrl, pveNode: n.pveNode, tokenId: n.tokenId, tokenSecret: n.tokenSecret });
46	}
