56	export async function backupRestore(job: Job): Promise<void> {
57	  const server = await loadServer(job.serverId!);
58	  if (SANDBOX) {
59	    // Simulate a successful restore — no Proxmox stop/restore/start.
60	    await notify(
61	      server.userId,
62	      `Backup restored on ${server.hostname}`,
63	      "Your server was restored from the selected backup (sandbox).",
64	      `/dashboard/servers/${server.id}`
65	    );
66	    return;
67	  }
68	  if (!server.vmid) throw new Error("restore: server has no VM");
69	
70	  const payload = (job.payload ?? {}) as { volid?: string };
71	  const volid = payload.volid;
72	  if (!volid) throw new Error("restore: missing volid");
73	
74	  const conn = await nodeFor(server);
75	  const vmid = server.vmid;
76	  const wasRunning = server.status === "RUNNING";
77	
78	  // 1) Stop the VM so the disk can be overwritten (ignore "already stopped").
79	  try {
80	    const stopUpid = await conn.post(`/nodes/${conn.node}/qemu/${vmid}/status/stop`, {});
81	    await conn.waitForTask(stopUpid);
82	  } catch {
83	    /* already stopped / not running */
84	  }
85	  await db.server.update({ where: { id: server.id }, data: { status: "STOPPED" } });
86	
87	  // 2) Restore the archive over the existing VMID (force overwrite). Storage is
88	  //    left to the archive's recorded config so disks land where they were.
89	  const restoreUpid = await conn.post(`/nodes/${conn.node}/qemu`, {
90	    vmid,
91	    archive: volid,
92	    force: 1,
93	  });
94	  await conn.waitForTask(restoreUpid, 3_600_000);
95	
96	  // 3) Bring the VM back up if it was running before the restore.
97	  if (wasRunning) {
98	    const startUpid = await conn.post(`/nodes/${conn.node}/qemu/${vmid}/status/start`, {});
99	    await conn.waitForTask(startUpid);
100	    await db.server.update({ where: { id: server.id }, data: { status: "RUNNING" } });
101	  }
102	
103	  await notify(
104	    server.userId,
105	    `Backup restored on ${server.hostname}`,
106	    "Your server was restored from the selected backup. Any changes made after that backup are gone.",
107	    `/dashboard/servers/${server.id}`
108	  );
109	}
