1	import { db } from "../lib/db";
2	import { SANDBOX } from "../lib/sandbox";
3	import { GAME_FAMILIES, type GameFamily } from "../lib/games";
4	import { execFile } from "node:child_process";
5	import { promisify } from "node:util";
6	import type { Job } from "@prisma/client";
7	
8	const execFileP = promisify(execFile);
9	
10	/**
11	 * Game-server auto-update handlers.
12	 *
13	 * `gameUpdate` runs a best-effort, per-family update command over SSH against
14	 * the server's private IP (the worker can reach vmbr1). `gameUpdateSweep` finds
15	 * RUNNING game servers with `autoUpdate=true` and enqueues GAME_UPDATE jobs for
16	 * them — safe to call periodically (it de-dupes on in-flight jobs).
17	 *
18	 * NOTE: `worker/index.ts` owns the job loop and its `handlers` map; wire these
19	 * in there (`GAME_UPDATE: gameUpdate`) and call `gameUpdateSweep()` on a timer.
20	 */
21	
22	/** Steam dedicated-server app IDs for steamcmd-based families. */
23	const STEAM_APPID: Partial<Record<GameFamily, string>> = {
24	  valheim: "896660",
25	  rust: "258550",
26	  palworld: "2394010",
27	  cs2: "730",
28	};
29	
30	/** systemd service name candidates per family (first that exists wins). */
31	const SERVICE_HINT: Record<GameFamily, string> = {
32	  minecraft: "minecraft",
33	  valheim: "valheim",
34	  rust: "rust",
35	  palworld: "palworld",
36	  cs2: "cs2",
37	  terraria: "terraria",
38	};
39	
40	/**
41	 * Build a best-effort remote update command. For steamcmd-based games we run an
42	 * anonymous `app_update ... validate` if steamcmd is present, then (always)
43	 * restart the matching systemd service. Everything is tolerant (`|| true`) so a
44	 * missing tool/service never fails the whole job for an otherwise-healthy VM.
45	 */
46	function updateCommand(family: GameFamily): string {
47	  const appId = STEAM_APPID[family];
48	  const svc = SERVICE_HINT[family];
49	  const steam = appId
50	    ? `if command -v steamcmd >/dev/null 2>&1; then steamcmd +login anonymous +app_update ${appId} validate +quit || true; fi; `
51	    : "";
52	  // Restart the named service, then a "<family>-server" variant, then any unit
53	  // whose name contains the family; never hard-fail.
54	  const restart =
55	    `systemctl restart ${svc} 2>/dev/null || ` +
56	    `systemctl restart ${svc}-server 2>/dev/null || ` +
57	    `svc=$(systemctl list-units --type=service --plain --no-legend 2>/dev/null | grep -i ${family} | head -1 | awk '{print $1}'); ` +
58	    `if [ -n "$svc" ]; then systemctl restart "$svc" || true; fi`;
59	  return `set -e; ${steam}${restart}; true`;
60	}
61	
62	async function loadGameServer(serverId: string) {
63	  const server = await db.server.findUnique({
64	    where: { id: serverId },
65	    include: { osTemplate: true },
66	  });
67	  if (!server) throw new Error(`Server ${serverId} not found`);
68	  return server;
69	}
70	
71	async function notify(userId: string, title: string, body?: string, href?: string) {
72	  try {
73	    await db.notification.create({ data: { userId, title, body, href } });
74	  } catch (e) {
75	    console.error("[game-update] notify failed", e);
76	  }
77	}
78	
79	/** Run the per-family update command over SSH (sshpass + private IP). */
80	export async function gameUpdate(job: Job): Promise<void> {
81	  const server = await loadGameServer(job.serverId!);
82	  if (SANDBOX) {
83	    // Simulate a successful update — no SSH to the (non-existent) VM.
84	    await notify(
85	      server.userId,
86	      `${server.osTemplate.name} updated on ${server.hostname}`,
87	      "The latest server update was applied (sandbox).",
88	      `/dashboard/servers/${server.id}`
89	    );
90	    return;
91	  }
92	  const family = server.osTemplate.family as GameFamily;
93	  if (!GAME_FAMILIES.includes(family)) {
94	    throw new Error(`game update: ${server.hostname} is not a game server`);
95	  }
96	  if (server.status !== "RUNNING") throw new Error("game update: server is not running");
97	  if (!server.ipAddress || !server.rootPassword) {
98	    throw new Error("game update: server has no IP/password yet");
99	  }
100	
101	  const remote = updateCommand(family);
102	  await execFileP(
103	    "sshpass",
104	    [
105	      "-p",
106	      server.rootPassword,
107	      "ssh",
108	      "-o",
109	      "StrictHostKeyChecking=no",
110	      "-o",
111	      "UserKnownHostsFile=/dev/null",
112	      "-o",
113	      "ConnectTimeout=15",
114	      `root@${server.ipAddress}`,
115	      remote,
116	    ],
117	    { timeout: 600_000, maxBuffer: 4 * 1024 * 1024 }
118	  );
119	
120	  await notify(
121	    server.userId,
122	    `${server.osTemplate.name} updated on ${server.hostname}`,
123	    "The latest server update was applied and the service was restarted.",
124	    `/dashboard/servers/${server.id}`
125	  );
126	}
127	
128	/**
129	 * Enqueue GAME_UPDATE jobs for every RUNNING game server that has opted into
130	 * auto-update and has no job already in flight. Idempotent / safe to call on a
131	 * timer. Returns nothing; logs a summary.
132	 */
133	export async function gameUpdateSweep(): Promise<void> {
134	  if (SANDBOX) return; // no game servers to update over SSH in the sandbox
135	  const candidates = await db.server.findMany({
136	    where: {
137	      status: "RUNNING",
138	      autoUpdate: true,
139	      osTemplate: { family: { in: [...GAME_FAMILIES] } },
140	    },
141	    select: { id: true, hostname: true },
142	  });
143	  if (candidates.length === 0) return;
144	
145	  let enqueued = 0;
146	  for (const s of candidates) {
147	    const inflight = await db.job.count({
148	      where: { serverId: s.id, status: { in: ["QUEUED", "RUNNING"] } },
149	    });
150	    if (inflight > 0) continue;
151	    await db.job.create({ data: { type: "GAME_UPDATE", serverId: s.id } });
152	    enqueued++;
153	  }
154	  if (enqueued > 0) console.log(`[game-update] sweep enqueued ${enqueued} update job(s)`);
155	}
