1	import { db } from "../lib/db";
2	import { SANDBOX } from "../lib/sandbox";
3	import {
4	  nodeStorageUsage,
5	  nodeRamUsage,
6	  backupSummary,
7	  stuckJobs,
8	  workerHealth,
9	  fmtAge,
10	  DISK_WARN_RATIO,
11	  RAM_WARN_RATIO,
12	  BACKUP_STALE_MS,
13	  QUEUE_BACKLOG_ALERT,
14	  STUCK_JOB_MS,
15	} from "../lib/monitoring";
16	
17	/**
18	 * Monitoring sweep — run periodically from the worker loop. Read-only checks
19	 * that raise dashboard notifications for all ADMINs when a threshold trips.
20	 *
21	 * Notifications are de-duplicated by title within a rolling window so a
22	 * persistent condition (e.g. a node stuck at 90% disk) alerts once every few
23	 * hours rather than every sweep.
24	 */
25	
26	const DEDUPE_HOURS = Number(process.env.NXEON_ALERT_DEDUPE_HOURS ?? 3);
27	
28	/**
29	 * Fan a single alert out to every ADMIN, unless an identically-titled alert
30	 * already went out within the dedupe window.
31	 */
32	export async function notifyAdmins(
33	  title: string,
34	  body: string,
35	  href = "/admin/monitoring"
36	): Promise<void> {
37	  const since = new Date(Date.now() - DEDUPE_HOURS * 60 * 60_000);
38	  const recent = await db.notification.findFirst({
39	    where: { title, createdAt: { gt: since } },
40	    select: { id: true },
41	  });
42	  if (recent) return;
43	
44	  const admins = await db.user.findMany({ where: { role: "ADMIN" }, select: { id: true } });
45	  if (admins.length === 0) return;
46	
47	  await db.notification.createMany({
48	    data: admins.map((a) => ({ userId: a.id, title, body, href })),
49	  });
50	}
51	
52	export async function monitorSweep(): Promise<void> {
53	  if (SANDBOX) return; // no real nodes/Proxmox to monitor in the sandbox
54	  // 1. Node disk usage > threshold
55	  try {
56	    const storage = await nodeStorageUsage();
57	    for (const s of storage) {
58	      if (s.reachable && s.total > 0 && s.ratio > DISK_WARN_RATIO) {
59	        const pct = Math.round(s.ratio * 100);
60	        await notifyAdmins(
61	          `Disk capacity warning — ${s.node}/${s.storage} at ${pct}%`,
62	          `Storage "${s.storage}" on node ${s.node} is ${pct}% full ` +
63	            `(${(s.avail / 1024 ** 3).toFixed(0)} GB free). Free space or add capacity to keep provisioning healthy.`
64	        );
65	      }
66	    }
67	  } catch (e) {
68	    console.error("[monitor] disk check error", e);
69	  }
70	
71	  // 2. Node RAM pressure > threshold
72	  try {
73	    const ram = await nodeRamUsage();
74	    for (const r of ram) {
75	      if (r.reachable && r.total > 0 && r.ratio > RAM_WARN_RATIO) {
76	        const pct = Math.round(r.ratio * 100);
77	        await notifyAdmins(
78	          `Memory pressure — ${r.node} at ${pct}%`,
79	          `Node ${r.node} RAM is ${pct}% used. New deploys may be refused until usage drops.`
80	        );
81	      }
82	    }
83	  } catch (e) {
84	    console.error("[monitor] ram check error", e);
85	  }
86	
87	  // 3. Stuck jobs (RUNNING beyond the stuck threshold)
88	  try {
89	    const stuck = await stuckJobs();
90	    if (stuck.length > 0) {
91	      const mins = Math.round(STUCK_JOB_MS / 60_000);
92	      const lines = stuck
93	        .slice(0, 8)
94	        .map(
95	          (j) =>
96	            `• ${j.type}${j.hostname ? ` (${j.hostname})` : ""} — running ${fmtAge(
97	              Date.now() - j.updatedAt.getTime()
98	            )}`
99	        )
100	        .join("\n");
101	      await notifyAdmins(
102	        `Stuck jobs — ${stuck.length} running > ${mins}m`,
103	        `The worker has job(s) stuck in RUNNING:\n${lines}`
104	      );
105	    }
106	  } catch (e) {
107	    console.error("[monitor] stuck-job check error", e);
108	  }
109	
110	  // 4. Worker liveness + pending-job backlog
111	  try {
112	    const wh = await workerHealth();
113	    if (wh.status === "down") {
114	      await notifyAdmins(
115	        "Worker appears stopped",
116	        wh.detail + ". Check the provisioning worker process."
117	      );
118	    }
119	    if (wh.queuedBacklog >= QUEUE_BACKLOG_ALERT) {
120	      await notifyAdmins(
121	        `Job backlog building — ${wh.queuedBacklog} queued`,
122	        `${wh.queuedBacklog} jobs are waiting in the queue. The worker may be overloaded or slow.`
123	      );
124	    }
125	  } catch (e) {
126	    console.error("[monitor] worker check error", e);
127	  }
128	
129	  // 5. Backup freshness (best-effort; skipped if backup storage isn't listable)
130	  try {
131	    const bk = await backupSummary();
132	    if (bk.reachable && bk.count > 0 && bk.newestCtime !== null) {
133	      const ageMs = Date.now() - bk.newestCtime * 1000;
134	      if (ageMs > BACKUP_STALE_MS) {
135	        await notifyAdmins(
136	          `Backups look stale — newest is ${fmtAge(ageMs)} old`,
137	          `The most recent backup on disk is ${fmtAge(ageMs)} old. Verify the backup schedule is running.`
138	        );
139	      }
140	    }
141	  } catch (e) {
142	    console.error("[monitor] backup check error", e);
143	  }
144	}
