9	/**
10	 * Server-ops actions: game-server auto-update toggle + "update now", and
11	 * self-service backup restore. Every action re-verifies ownership.
12	 */
13	
14	async function ownedServer(serverId: string) {
15	  const user = await requireUser();
16	  const server = await db.server.findUnique({
17	    where: { id: serverId },
18	    include: { osTemplate: true },
19	  });
20	  if (!server) throw new Error("Not found");
21	  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
22	  return { user, server };
23	}
24	
25	/** Is this server's image a managed game family? */
26	function isGameServer(server: { osTemplate: { family: string } }): boolean {
27	  return GAME_FAMILIES.includes(server.osTemplate.family as GameFamily);
28	}
29	
30	/** Reject if another job is already queued/running on this server. */
31	async function ensureIdle(serverId: string): Promise<{ error?: string }> {
32	  const pending = await db.job.count({
33	    where: { serverId, status: { in: ["QUEUED", "RUNNING"] } },
34	  });
35	  if (pending > 0) return { error: "Another operation is already in progress on this server." };
36	  return {};
37	}
