39	// ---------- Game-server auto-update ----------
40	
41	/**
42	 * Toggle `Server.autoUpdate` for a game server. Read-only for non-game images
43	 * (returns an error). The periodic worker sweep uses this flag.
44	 */
45	export async function toggleAutoUpdate(
46	  serverId: string,
47	  enabled: boolean
48	): Promise<{ error?: string; autoUpdate?: boolean }> {
49	  const { user, server } = await ownedServer(serverId);
50	  if (!isGameServer(server)) return { error: "Auto-update is only available for game servers." };
51	
52	  await db.server.update({ where: { id: server.id }, data: { autoUpdate: enabled } });
53	  await db.auditLog.create({
54	    data: {
55	      userId: user.id,
56	      action: "server.auto_update_toggle",
57	      detail: `${serverId} -> ${enabled ? "on" : "off"}`,
58	    },
59	  });
60	  revalidatePath(`/dashboard/servers/${serverId}`);
61	  return { autoUpdate: enabled };
62	}
