64	/**
65	 * Enqueue a one-off GAME_UPDATE job. The worker SSHes the per-family update
66	 * command over the private network, so the VM must be running.
67	 */
68	export async function triggerGameUpdate(serverId: string): Promise<{ error?: string }> {
69	  const { user, server } = await ownedServer(serverId);
70	  if (!isGameServer(server)) return { error: "Updates are only available for game servers." };
71	  if (server.status !== "RUNNING") {
72	    return { error: "Server must be running to apply a game update." };
73	  }
74	  if (!server.ipAddress || !server.rootPassword) {
75	    return { error: "Server is still provisioning — try again shortly." };
76	  }
77	  const idle = await ensureIdle(serverId);
78	  if (idle.error) return idle;
79	
80	  await db.job.create({ data: { type: "GAME_UPDATE", serverId } });
81	  await db.auditLog.create({
82	    data: { userId: user.id, action: "server.game_update", detail: serverId },
83	  });
