2	
3	/**
4	 * Owned-server-scoped server actions for the in-portal file manager.
5	 *
6	 * Every action:
7	 *   - authenticates the caller and verifies they OWN the target server
8	 *     (admins may act on any server), mirroring the `ownedServer` pattern in
9	 *     lib/actions-server-lifecycle.ts;
10	 *   - normalizes + validates the path (rejects `..` traversal, requires an
11	 *     absolute path, clamps length) via lib/sftp helpers;
12	 *   - enforces size limits on text edits;
13	 *   - rate-limits per user;
14	 *   - returns a typed { ok, error?, ... } result — never throws raw internals
15	 *     at the client, and never exposes another user's server.
16	 *
17	 * The heavy lifting (real SFTP vs. sandbox simulation) lives in lib/sftp.ts.
18	 */
19	import { db } from "./db";
20	import { requireUser } from "./auth";
21	import { checkRateLimit } from "./rate-limit";
22	import {
23	  listDir,
24	  statPath,
25	  readFileText,
26	  writeFileText,
27	  mkdirPath,
28	  renamePath,
29	  removePath,
30	  chmodPath,
31	  normalizePath,
32	  validateName,
33	  joinPath,
34	  type SftpEntry,
35	} from "./sftp";
36	
37	/** Max size (bytes) for a text file opened/saved in the inline editor. */
38	const MAX_EDIT_BYTES = 1024 * 1024; // ~1 MB
39	
40	export type FileEntry = {
41	  name: string;
42	  isDirectory: boolean;
43	  size: number;
44	  modifiedMs: number;
45	  /** Octal permission string like "755", or null if unknown. */
46	  mode: string | null;
47	};
48	
49	type ListResult = { ok: true; path: string; entries: FileEntry[] } | { ok: false; error: string };
50	type ReadResult =
51	  | { ok: true; path: string; content: string; truncated: false }
52	  | { ok: false; error: string };
53	type MutResult = { ok: true } | { ok: false; error: string };
54	
55	/**
56	 * Load the server if (and only if) the caller owns it (or is an admin). Returns
57	 * the exact fields lib/sftp needs to open a connection. Throws generic errors
58	 * that the wrappers translate to typed results.
59	 */
60	async function ownedServer(serverId: string) {
61	  const user = await requireUser();
62	  const server = await db.server.findUnique({
63	    where: { id: serverId },
64	    select: {
65	      id: true,
66	      userId: true,
67	      status: true,
68	      rootPassword: true,
69	      sshPort: true,
70	      dedicatedIp: { select: { address: true } },
71	    },
72	  });
73	  if (!server) throw new Error("Not found");
74	  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
75	  return { user, server };
76	}
77	
78	/** Per-user throttle. Returns an error string when the caller should back off. */
79	function throttle(userId: string, op: string, max: number): string | null {
80	  const rl = checkRateLimit(`files:${op}:${userId}`, { max, windowMs: 60_000 });
81	  if (!rl.ok) return `Too many requests — slow down and retry in ${rl.retryAfterSec}s.`;
82	  return null;
83	}
84	
85	function toMode(mode: number | null): string | null {
86	  return mode == null ? null : (mode & 0o777).toString(8).padStart(3, "0");
87	}
88	
89	function entryOut(e: SftpEntry): FileEntry {
90	  return {
91	    name: e.name,
92	    isDirectory: e.isDirectory,
93	    size: e.size,
94	    modifiedMs: e.modifiedMs,
95	    mode: toMode(e.mode),
96	  };
97	}
98	
99	/** Map an internal error to a safe, user-facing message. */
100	function safeError(err: unknown): string {
101	  const msg = err instanceof Error ? err.message : String(err);
102	  if (msg === "Not found" || msg === "Forbidden") return "Server not found.";
103	  // Path/traversal/size messages from lib/sftp are already user-safe.
104	  if (
105	    /traversal|absolute|too long|too large|Invalid|No such|Not a (file|directory)|already exists|reachable|root password|is a directory/i.test(
106	      msg
107	    )
108	  ) {
109	    return msg;
110	  }
111	  // Anything else (connection/protocol errors) — keep it generic.
112	  return "Could not reach the server's filesystem. Please try again shortly.";
113	}
114	
115	// ---------------------------------------------------------------------------
116	
117	export async function listFiles(serverId: string, path: string): Promise<ListResult> {
118	  try {
119	    const { user, server } = await ownedServer(serverId);
120	    const limited = throttle(user.id, "list", 120);
121	    if (limited) return { ok: false, error: limited };
122	    const clean = normalizePath(path || "/");
123	    const entries = await listDir(server, clean);
124	    return { ok: true, path: clean, entries: entries.map(entryOut) };
125	  } catch (err) {
126	    return { ok: false, error: safeError(err) };
127	  }
128	}
129	
130	export async function readFile(serverId: string, path: string): Promise<ReadResult> {
131	  try {
132	    const { user, server } = await ownedServer(serverId);
133	    const limited = throttle(user.id, "read", 120);
