1	// "Build with Claude AI" worker handler — SAFE, plan-then-approve.
2	//
3	// Two phases, driven by ClaudeBuild.approved:
4	//   1. PLAN  (approved=false): ask Claude — with the OWNER'S effective key — for
5	//      an ordered JSON array of non-destructive shell commands. Store it to
6	//      ClaudeBuild.plan and set AWAITING_APPROVAL. NOTHING is executed.
7	//   2. EXECUTE (approved=true): run each approved command over SSH, enforcing a
8	//      denylist, a per-command timeout, and a hard command cap. Append output to
9	//      ClaudeBuild.log, then set DONE (or FAILED on error). Never runs a command
10	//      that was not part of the approved plan.
11	//
12	// This handler is wired into worker/index.ts's `handlers` map by the
13	// orchestrator (see INTEGRATION NEEDED in the final report):
14	//   import { claudeBuild } from "./claude";
15	//   CLAUDE_BUILD: claudeBuild,
16	
17	import { execFile } from "node:child_process";
18	import { promisify } from "node:util";
19	import { db } from "../lib/db";
20	import { askClaude, effectiveKeyFor, type ClaudeMessage } from "../lib/anthropic";
21	import { SANDBOX } from "../lib/sandbox";
22	import type { Job } from "@prisma/client";
23	
24	const execFileAsync = promisify(execFile);
25	
26	/** Hard cap on the number of commands executed for a single build. */
27	export const CLAUDE_MAX_COMMANDS = 20;
28	
29	/** Per-command SSH execution timeout. */
30	const CMD_TIMEOUT_MS = 120_000;
31	/** Cap on captured output per command (chars) to keep the log bounded. */
32	const MAX_OUTPUT_CHARS = 4000;
33	/** Cap on total stored log size. */
34	const MAX_LOG_CHARS = 60_000;
35	
36	type PlanStep = { cmd: string; intent: string };
37	
38	const PLAN_SYSTEM_PROMPT = `You are an expert Linux server administrator. You are given a goal for a SINGLE Debian/Ubuntu server that you operate on over SSH as root. Produce a PLAN — do NOT run anything.
39	
40	Output ONLY a JSON array of steps and NOTHING else (no markdown, no backticks, no prose before or after). Each step is an object:
41	{"cmd": "<one non-interactive shell command>", "intent": "<short plain-English explanation of what it does and why>"}
42	
43	Rules for the plan:
44	- Operate ONLY on this one server. Never touch other hosts, networks, or cloud APIs.
45	- Commands must be non-interactive: use flags like -y and DEBIAN_FRONTEND=noninteractive; never launch editors, pagers, REPLs, or anything that waits for input.
46	- NON-DESTRUCTIVE ONLY. Absolutely no whole-disk or whole-system operations: no rm -rf /, no mkfs/fdisk/dd on disks, no wiping /etc, no reboot/shutdown/poweroff/halt, no user/password changes, no disabling SSH.
47	- Keep each command self-contained and idempotent where possible.
48	- Prefer standard packages and services (apt, systemctl, nginx, ufw, etc.).
49	- At most ${CLAUDE_MAX_COMMANDS} steps. If the goal cannot be met safely, return an empty array [].`;
50	
51	/** Escape a string for safe single-quoted inclusion in a bash -c argument. */
52	function shSingleQuote(s: string): string {
53	  return `'${s.replace(/'/g, `'\\''`)}'`;
54	}
55	
56	/** Reject catastrophic commands as a defense-in-depth backstop (denylist). */
57	function isForbidden(cmd: string): boolean {
58	  const c = cmd.toLowerCase();
59	  const patterns = [
60	    /rm\s+(-[a-z]*\s+)*(-[a-z]*r[a-z]*f|-[a-z]*f[a-z]*r)\s+\/(\s|$)/, // rm -rf /
61	    /\bmkfs\b/,
62	    /\bfdisk\b/,
63	    /\bparted\b/,
64	    /\bdd\b[^|]*of=\/dev\//, // dd of=/dev/*
65	    /\b(reboot|shutdown|poweroff|halt|init\s+0|init\s+6)\b/,
66	    /\bshred\b/,
67	    /\bpasswd\b/,
68	    /:\(\)\s*\{.*\};:/, // fork bomb :(){ :|:& };:
69	    />\s*\/dev\/sd[a-z]/,
70	    /\bsystemctl\s+(stop|disable|mask)\s+(ssh|sshd)\b/,
71	  ];
72	  return patterns.some((p) => p.test(c));
73	}
