157	export async function claudeBuild(job: Job): Promise<void> {
158	  const payload = (job.payload ?? {}) as { buildId?: string };
159	  const buildId = payload.buildId;
160	  if (!buildId) throw new Error("claudeBuild: missing buildId in job payload");
161	
162	  const build = await db.claudeBuild.findUnique({ where: { id: buildId }, include: { server: true } });
163	  if (!build) throw new Error(`claudeBuild: build ${buildId} not found`);
164	  const server = build.server;
165	
166	  // Terminal builds are never re-processed by a stray/duplicate job.
167	  if (build.status === "DONE" || build.status === "FAILED") return;
168	
169	  if (SANDBOX) {
170	    // Simulate the plan-then-approve flow with no Anthropic call and no SSH.
171	    if (!build.approved) {
172	      await db.claudeBuild.update({
173	        where: { id: buildId },
174	        data: {
175	          status: "AWAITING_APPROVAL",
176	          plan: JSON.stringify([{ cmd: "echo sandbox build", intent: "Sandbox simulated step" }]),
177	        },
178	      });
179	    } else {
180	      await db.claudeBuild.update({
181	        where: { id: buildId },
182	        data: {
183	          status: "DONE",
184	          steps: 1,
185	          log: truncate((build.log ?? "") + "\n[sandbox] simulated build completed\n", MAX_LOG_CHARS),
186	        },
187	      });
188	      await db.notification
189	        .create({
190	          data: {
191	            userId: build.userId,
192	            title: `Claude finished building on ${server?.hostname ?? "your server"}`,
193	            body: build.prompt.slice(0, 140),
194	            href: `/dashboard/build`,
195	          },
196	        })
197	        .catch(() => {});
198	    }
199	    return;
200	  }
201	
202	  // Everything is gated on an effective owner key + a reachable RUNNING server.
203	  const owner = await db.user.findUnique({
204	    where: { id: build.userId },
205	    select: { anthropicKeyEnc: true },
206	  });
207	  const apiKey = effectiveKeyFor(owner);
208	  if (!apiKey) {
209	    await failBuild(buildId, build.log ?? "", "No Anthropic API key available for the owner.");
210	    return;
211	  }
212	  if (!server || server.status !== "RUNNING") {
213	    await failBuild(buildId, build.log ?? "", "The server is not running.");
214	    return;
215	  }
216	  if (!server.ipAddress || !server.rootPassword) {
217	    await failBuild(buildId, build.log ?? "", "The server is not reachable (no IP or root password).");
218	    return;
219	  }
220	
221	  if (!build.approved) {
222	    await planPhase(buildId, build.status, build.prompt, build.log ?? "", apiKey);
223	  } else {
224	    await executePhase(buildId, build.prompt, build.plan, build.log ?? "", server);
225	  }
226	}
