228	/** Phase 1: ask Claude for a plan, store it, and await owner approval. */
229	async function planPhase(
230	  buildId: string,
231	  status: string,
232	  prompt: string,
233	  priorLog: string,
234	  apiKey: string
235	): Promise<void> {
236	  // Only plan for a not-yet-planned build; ignore duplicate jobs otherwise.
237	  if (status !== "QUEUED" && status !== "PLANNING") return;
238	
239	  await db.claudeBuild.update({ where: { id: buildId }, data: { status: "PLANNING" } });
240	
241	  const messages: ClaudeMessage[] = [
242	    { role: "user", content: `Goal: ${prompt}\n\nProduce the plan now as a JSON array of {"cmd","intent"} steps.` },
243	  ];
244	
245	  let reply: string;
246	  try {
247	    reply = await askClaude(apiKey, messages, PLAN_SYSTEM_PROMPT, { maxTokens: 4096, timeoutMs: 90_000 });
248	  } catch (e: any) {
249	    await failBuild(buildId, priorLog, `Planning failed: ${e?.message ?? e}`);
250	    return;
251	  }
252	
253	  const plan = parsePlan(reply);
254	  if (!plan) {
255	    await failBuild(buildId, priorLog, "Claude did not return a usable plan for this goal.");
256	    return;
257	  }
258	
259	  const capped = plan.slice(0, CLAUDE_MAX_COMMANDS);
260	  await db.claudeBuild.update({
261	    where: { id: buildId },
262	    data: { status: "AWAITING_APPROVAL", plan: JSON.stringify(capped) },
263	  });
264	}
265	
266	/** Phase 2: execute the OWNER-APPROVED plan over SSH. */
267	async function executePhase(
268	  buildId: string,
269	  prompt: string,
270	  planJson: string | null,
271	  priorLog: string,
272	  server: { ipAddress: string | null; rootPassword: string | null; hostname: string | null }
273	): Promise<void> {
274	  let plan: PlanStep[] = [];
275	  try {
276	    const parsed = JSON.parse(planJson ?? "[]");
277	    if (Array.isArray(parsed)) {
278	      plan = parsed
279	        .map((s: any) => ({ cmd: String(s?.cmd ?? s ?? "").trim(), intent: String(s?.intent ?? "") }))
280	        .filter((s: PlanStep) => s.cmd);
281	    }
282	  } catch {
283	    plan = [];
284	  }
285	
286	  if (plan.length === 0) {
287	    await failBuild(buildId, priorLog, "No approved plan to execute.");
288	    return;
289	  }
290	
291	  await db.claudeBuild.update({ where: { id: buildId }, data: { status: "RUNNING" } });
292	
293	  const commands = plan.slice(0, CLAUDE_MAX_COMMANDS);
294	  let log = priorLog;
295	  const append = async (chunk: string, steps: number) => {
296	    log = truncate(log + chunk, MAX_LOG_CHARS);
297	    await db.claudeBuild.update({ where: { id: buildId }, data: { log, steps } });
298	  };
299	
300	  await append(`# Goal: ${prompt}\n# Executing approved plan (${commands.length} command(s))\n\n`, 0);
301	
302	  let steps = 0;
303	  let finalStatus: "DONE" | "FAILED" = "DONE";
304	
305	  try {
306	    for (const step of commands) {
307	      const command = step.cmd;
308	
309	      // Defense-in-depth: even an approved plan is re-checked against the denylist.
310	      if (isForbidden(command)) {
311	        await append(`\n$ ${command}\n[nxeon] Skipped — blocked by the safety denylist.\n`, steps);
312	        continue;
313	      }
314	
315	      steps += 1;
316	      const { output, failed } = await sshExec(server, command);
317	      const shown = truncate(output, MAX_OUTPUT_CHARS);
318	      await append(`\n$ ${command}\n${shown}\n`, steps);
319	
320	      if (failed) {
321	        await append(`\n[nxeon] Command failed — stopping execution.\n`, steps);
322	        finalStatus = "FAILED";
323	        break;
324	      }
325	    }
326	  } catch (e: any) {
327	    await append(`\n[nxeon] Build error: ${e?.message ?? e}\n`, steps);
328	    finalStatus = "FAILED";
329	  }
330	
331	  await db.claudeBuild.update({ where: { id: buildId }, data: { status: finalStatus, steps } });
332	
333	  try {
334	    await db.notification.create({
335	      data: {
336	        userId: (await db.claudeBuild.findUnique({ where: { id: buildId }, select: { userId: true } }))!.userId,
337	        title:
338	          finalStatus === "DONE"
339	            ? `Claude finished building on ${server.hostname}`
340	            : `Claude build failed on ${server.hostname}`,
341	        body: prompt.slice(0, 140),
342	        href: `/dashboard/build`,
343	      },
344	    });
345	  } catch {
346	    /* notification is best-effort */
347	  }
348	}
