94	export async function resizeServer(serverId: string, planId: string): Promise<{ error?: string }> {
95	  const { user, server } = await ownedServer(serverId);
96	  const newPlan = await db.plan.findUnique({ where: { id: planId } });
97	  if (!newPlan?.active) return { error: "Plan not available." };
98	  if (newPlan.id === server.planId) return { error: "Server is already on this plan." };
99	  if (newPlan.diskGB < server.plan.diskGB) {
100	    return { error: "Disk storage can only grow — choose a plan with equal or larger disk." };
101	  }
102	  if (newPlan.priceCents < server.plan.priceCents) {
103	    return { error: "Downgrades aren't self-service yet — please contact support." };
104	  }
105	  if (!["RUNNING", "STOPPED"].includes(server.status)) return { error: "Server is busy." };
106	
107	  // Prorate the upgrade over the ACTUAL remaining duration, not a fraction of a
108	  // single term. `renewNow` can stack expiresAt many terms into the future, so a
109	  // "fraction of one term" clamp let a customer who prepaid e.g. 13 months upgrade
110	  // for only ~1 term of the delta. Charge the monthly price difference for every
111	  // remaining month instead. Null expiresAt (free/admin servers) => 0.
112	  let prorateCents = 0;
113	  if (!server.isFree && server.expiresAt) {
114	    const now = Date.now();
115	    const remainingMonths = Math.max(0, (server.expiresAt.getTime() - now) / MS_PER_AVG_MONTH);
116	    const monthlyDelta = newPlan.priceCents - server.plan.priceCents; // plan.priceCents is the monthly price
117	    prorateCents = Math.max(0, Math.round(monthlyDelta * remainingMonths));
118	    if (prorateCents > 0 && user.balanceCents < prorateCents) {
119	      return {
120	        error: `Upgrading costs $${(prorateCents / 100).toFixed(2)} for the rest of your term. Top up your wallet first.`,
121	      };
122	    }
123	  }
124	
125	  const pending = await db.job.count({ where: { serverId, status: { in: ["QUEUED", "RUNNING"] } } });
126	  if (pending > 0) return { error: "Another operation is already in progress on this server." };
127	
128	  try {
129	    await db.$transaction(async (tx) => {
130	      if (prorateCents > 0) {
131	        await debitWallet(tx, server.userId, prorateCents);
132	        await tx.walletTransaction.create({
133	          data: { userId: server.userId, amountCents: -prorateCents, description: `Upgrade to ${newPlan.name} (prorated) — ${server.hostname}` },
134	        });
135	        // PAID invoice for the proration charge (one per user-initiated resize).
136	        await tx.invoice.create({
137	          data: invoiceCreateData({
138	            userId: server.userId,
139	            description: `Upgrade to ${newPlan.name} (prorated) — ${server.hostname}`,
140	            status: "PAID",
141	            lineItems: [
142	              { description: `Upgrade to ${newPlan.name} — prorated for remaining term (${server.hostname})`, qty: 1, unitCents: prorateCents, amountCents: prorateCents },
143	            ],
144	          }),
145	        });
146	      }
147	      // Record the amount charged on the job so the worker's RESIZE handler can
148	      // REVERSE it (credit `payload.prorateCents` back to the wallet) if the
149	      // resize terminally fails — money is committed here, before the job runs.
150	      // INTEGRATION NEEDED: worker must honour payload.prorateCents/direction.
151	      await tx.job.create({
152	        data: { type: "RESIZE", serverId, payload: { planId, prorateCents, direction: "up" } as any },
153	      });
154	      await tx.auditLog.create({
155	        data: { userId: user.id, action: "server.resize", detail: `${serverId} -> ${newPlan.slug} prorate=${prorateCents}` },
156	      });
157	    });
158	  } catch (e) {
159	    if (e instanceof InsufficientBalanceError) return { error: "Insufficient balance — top up your wallet first." };
160	    throw e;
161	  }
162	  revalidatePath(`/dashboard/servers/${serverId}`);
163	  return {};
164	}
