259	/**
260	 * Locate the first existing path: try explicit candidates via `test -f`, then a
261	 * bounded `find` over `findRoots` for `findName`. Returns the path or null.
262	 * Non-destructive — only reads.
263	 */
264	async function remoteLocate(
265	  conn: Client,
266	  candidates: string[],
267	  findRoots: string[],
268	  findName: string
269	): Promise<string | null> {
270	  const testExpr = candidates.map((p) => `if [ -f '${shq(p)}' ]; then echo '${shq(p)}'; exit 0; fi;`).join(" ");
271	  const findExpr = findRoots.length
272	    ? `for r in ${findRoots.map((r) => `'${shq(r)}'`).join(" ")}; do [ -d "$r" ] && find "$r" -maxdepth 6 -type f -name '${shq(findName)}' 2>/dev/null | head -1; done | head -1`
273	    : "true";
274	  const { stdout } = await execRemote(conn, `${testExpr} ${findExpr}`);
275	  const hit = stdout.split(/\r?\n/).map((s) => s.trim()).find((s) => s.length > 0);
276	  return hit ?? null;
277	}
