308	/** Update `key=value` lines in place, preserving comments/unknown lines; append missing keys. */
309	function updateKeyValue(content: string, updates: Record<string, string>): string {
310	  const lines = content.split(/\r?\n/);
311	  const seen = new Set<string>();
312	  for (let i = 0; i < lines.length; i++) {
313	    const trimmed = lines[i].trim();
314	    if (!trimmed || trimmed.startsWith("#") || trimmed.startsWith("!")) continue;
315	    const eq = lines[i].indexOf("=");
316	    if (eq < 0) continue;
317	    const key = lines[i].slice(0, eq).trim();
318	    if (Object.prototype.hasOwnProperty.call(updates, key)) {
319	      lines[i] = `${key}=${updates[key]}`;
320	      seen.add(key);
321	    }
322	  }
323	  for (const k of Object.keys(updates)) {
324	    if (!seen.has(k)) lines.push(`${k}=${updates[k]}`);
325	  }
326	  return lines.join("\n");
327	}
