610	
611	/** Split a comma-separated OptionSettings body at top level (respecting quotes). */
612	function splitTopLevel(s: string): string[] {
613	  const out: string[] = [];
614	  let cur = "";
615	  let inQuote = false;
616	  for (const ch of s) {
617	    if (ch === '"') inQuote = !inQuote;
618	    if (ch === "," && !inQuote) {
619	      out.push(cur);
620	      cur = "";
621	    } else {
622	      cur += ch;
623	    }
624	  }
625	  if (cur.length) out.push(cur);
626	  return out;
627	}
