629	/**
630	 * Update keys inside the `OptionSettings=(...)` block, preserving the section
631	 * header, all other keys, and quoting. Returns null if the block can't be parsed
632	 * (so the caller soft-fails instead of clobbering the file).
633	 */
634	function updatePalworld(content: string, updates: Record<string, string>): string | null {
635	  const idx = content.indexOf("OptionSettings=(");
636	  if (idx < 0) return null;
637	  const open = content.indexOf("(", idx);
638	  const close = content.indexOf(")", open);
639	  if (open < 0 || close < 0) return null;
640	
641	  const inner = content.slice(open + 1, close);
642	  const pairs = splitTopLevel(inner);
643	  const order: string[] = [];
644	  const map = new Map<string, string>();
645	  for (const p of pairs) {
646	    const eq = p.indexOf("=");
647	    if (eq < 0) continue;
648	    const k = p.slice(0, eq).trim();
649	    order.push(k);
650	    map.set(k, p.slice(eq + 1));
651	  }
652	  for (const [k, val] of Object.entries(updates)) {
653	    if (!map.has(k)) order.push(k);
654	    map.set(k, val);
655	  }
656	  const rebuilt = order.map((k) => `${k}=${map.get(k)}`).join(",");
657	  return content.slice(0, open + 1) + rebuilt + content.slice(close);
658	}
